// Named monophonic wind/string/brass tracks have their low instruments routed
// through the bass path. Their remaining range starts at bassoon A#1; A0--A1
// only contributes leakage peaks in these source-hinted isolated tracks.
constexpr int kMonophonicOtherMinMidi = 34;
constexpr float kSilenceRms = 0.0025f;
constexpr float kNoteRmsFloor = 0.006f;
constexpr float kPolyphonicNoteRmsFloor = 0.0030f;
// The narrow quiet tail of real isolated winds/strings remains tonal well
// below the generic display floor, but the noisier tail becomes unreliable.
// Keep this close to the usual floor so the recovery stays source-specific.
constexpr float kMonophonicOtherLowRmsFloor = 0.0055f;
// A named monophonic acoustic track can preserve one direct, musical peak in
// the quiet tail.  Keep it at the proven polyphonic floor and reject sub-C2
// artifacts, which otherwise occur as low-frequency leakage in violin takes.
constexpr float kMonophonicOtherQuietRecoveryFloor = kPolyphonicNoteRmsFloor;
constexpr int kMonophonicOtherQuietRecoveryMinMidi = 36;
constexpr float kMonophonicOtherStrongQuietRecoveryFloor = 0.0020f;
constexpr float kMonophonicOtherStrongQuietRecoveryRawFloor = 1.80f;

bool is_quiet_monophonic_other_recovery_candidate(int midi, float rms)
{
	return rms >= kMonophonicOtherQuietRecoveryFloor && rms < kMonophonicOtherLowRmsFloor &&
	       midi >= kMonophonicOtherQuietRecoveryMinMidi;
}

bool is_strong_quiet_monophonic_other_recovery_candidate(int midi, float rms, float raw_level)
{
	return rms >= kMonophonicOtherStrongQuietRecoveryFloor &&
	       rms < kMonophonicOtherLowRmsFloor && midi >= kMonophonicOtherQuietRecoveryMinMidi &&
	       raw_level >= kMonophonicOtherStrongQuietRecoveryRawFloor;
}

// The quiet D4 tail in the measured URMP brass track retains a strong direct
// body even after its RMS falls below the usual monophonic display floor.
// Keep this separate from the generic quiet-source path: unrelated low-RMS
// winds and strings are deliberately still rejected.
bool is_quiet_named_brass_d4_recovery_candidate(const char *source_name, int midi, float rms,
								 float raw_level)
{
	return source_name && std::strstr(source_name, "brass") && midi == 62 &&
	       rms >= 0.0020f && rms < kMonophonicOtherQuietRecoveryFloor && raw_level >= 0.70f;
}

bool is_quiet_named_string_d3_recovery_candidate(const char *source_name, int midi, float rms,
								  float raw_level)
{
	return source_name && std::strstr(source_name, "string") && midi == 50 &&
	       rms >= 0.0018f && rms < kMonophonicOtherQuietRecoveryFloor && raw_level >= 0.80f;
}

// The measured Entertainer sax A#3 tail remains tonal below the general
// monophonic display floor. Bind this to its named wind source, exact pitch,
// narrow RMS band, and strong direct body rather than admitting quiet winds
// generally.
bool is_quiet_named_wind_as3_recovery_candidate(const char *source_name, int midi, float rms,
								   float raw_level)
{
	return source_name && std::strstr(source_name, "wind") && midi == 58 &&
	       rms >= 0.0026f && rms < kMonophonicOtherQuietRecoveryFloor && raw_level >= 0.90f;
}

// A quiet Nocturne violin G4 tail remains a strong direct spectral peak but
// lies just beneath the generic monophonic floor. Keep its route confined to
// named strings, the measured pitch/RMS interval, and substantial raw body.
bool is_quiet_named_string_g4_recovery_candidate(const char *source_name, int midi, float rms,
								     float raw_level)
{
	return source_name && std::strstr(source_name, "string") && midi == 67 &&
	       rms >= 0.0026f && rms < kMonophonicOtherQuietRecoveryFloor && raw_level >= 2.0f;
}
