bool measured_other_owned_low_d_sharp_vocal_body_supported(const FullMixDebugCandidate &debug)
{
	// A low D# vocal fundamental can be classified as Other when its second
	// harmonic is stronger than the sparse vocal template expects.  This
	// compact profile is bounded away from the nearby acoustic-string and brass
	// shapes by its ownership split, spectral envelope, and partial ratios.
	if (debug.owner != InstrumentKind::Other || debug.midi != 51)
		return false;

	const float second = debug.harmonic_ratios[1];
	const float third = debug.harmonic_ratios[2];
	const float fourth = debug.harmonic_ratios[3];
	const float fifth = debug.harmonic_ratios[4];
	return debug.other_score >= 0.68f && debug.other_score <= 0.76f &&
	       debug.keyboard_score >= 0.12f && debug.keyboard_score <= 0.20f &&
	       debug.guitar_score >= 0.09f && debug.guitar_score <= 0.15f &&
	       debug.vocal_score <= 0.020f &&
	       debug.spectral_level >= 0.90f &&
	       debug.pitch_confidence >= 0.80f && debug.pitch_confidence <= 0.86f &&
	       debug.periodicity >= 0.80f && debug.periodicity <= 0.88f &&
	       debug.harmonic_fit_error >= 0.10f && debug.harmonic_fit_error <= 0.18f &&
	       debug.spectral_centroid >= 0.34f && debug.spectral_centroid <= 0.45f &&
	       debug.spectral_slope >= 0.60f && debug.spectral_slope <= 0.90f &&
	       debug.local_noise_level >= 0.18f && debug.local_noise_level <= 0.28f &&
	       second >= 0.25f && second <= 0.40f &&
	       third >= 0.40f && third <= 0.70f &&
	       fourth >= 0.15f && fourth <= 0.40f &&
	       fifth >= 0.05f && fifth <= 0.28f;
}

bool measured_other_owned_low_harmonic_vocal_body_supported(const FullMixDebugCandidate &debug)
{
	// Some sustained female-vocal fundamentals have a compact mid-band envelope
	// that the ownership classifier assigns to Other.  Unlike the nearby reed
	// and string profiles, these have a clean, low-harmonicity fit and a
	// moderate spectral slope.  Keep this span narrow: it is only a display
	// exception, not an ownership reclassification.
	if (debug.owner != InstrumentKind::Other || debug.midi < 54 || debug.midi > 64)
		return false;

	const float second = debug.harmonic_ratios[1];
	const float third = debug.harmonic_ratios[2];
	const float fourth = debug.harmonic_ratios[3];
	const float fifth = debug.harmonic_ratios[4];
	return debug.other_score >= 0.65f && debug.other_score <= 0.95f &&
	       debug.keyboard_score <= 0.25f && debug.guitar_score <= 0.28f &&
	       debug.vocal_score <= 0.020f && debug.spectral_level >= 0.86f &&
	       debug.pitch_confidence >= 0.80f && debug.pitch_confidence <= 0.93f &&
	       debug.periodicity >= 0.82f && debug.periodicity <= 0.95f &&
	       debug.harmonicity >= 0.85f && debug.harmonicity <= 1.80f &&
	       debug.harmonic_fit_error >= 0.04f && debug.harmonic_fit_error <= 0.22f &&
	       debug.spectral_centroid >= 0.30f && debug.spectral_centroid <= 0.47f &&
	       debug.spectral_slope >= 0.30f && debug.spectral_slope <= 0.80f &&
	       debug.local_noise_level >= 0.020f && debug.local_noise_level <= 0.40f &&
	       second >= 0.40f && second <= 0.75f && third >= 0.15f && third <= 0.70f &&
	       fourth >= 0.04f && fourth <= 0.60f && fifth >= 0.02f && fifth <= 0.40f;
}

bool measured_other_owned_vocal_shadow_suppression_supported(const FullMixDebugCandidate &debug,
							     float vocal_level, float owner_level)
{
	if (debug.owner != InstrumentKind::Other)
		return false;
	if (debug.midi < kFullMixVocalMinMidi || debug.midi > kVocalMaxMidi)
		return false;

	const float third = debug.harmonic_ratios[2];
	const float fourth = debug.harmonic_ratios[3];
	const float fifth = debug.harmonic_ratios[4];
	const bool low_noise_shadow = debug.local_noise_level <= 0.078f;
	const bool low_centered_formant_shadow =
		debug.spectral_centroid <= 0.514f &&
		third <= 1.24f &&
		fifth <= 0.35f;
	const bool high_centered_low_fifth_shadow =
		debug.spectral_centroid >= 0.534f &&
		third >= 1.20f &&
		fourth <= 0.95f &&
		fifth <= 0.35f;
	const bool low_visual_ratio = owner_level > 0.0f && vocal_level <= owner_level * 0.40f;
	const bool strong_other_sparse_shadow =
		debug.other_score >= 0.82f &&
		debug.vocal_score <= 0.020f &&
		debug.spectral_centroid <= 0.514f &&
		(debug.local_noise_level <= 0.16f ||
		 (debug.local_noise_level <= 0.17f && low_visual_ratio)) &&
		third >= 1.20f &&
		fourth <= 0.75f;
	return low_noise_shadow || low_centered_formant_shadow || high_centered_low_fifth_shadow ||
	       strong_other_sparse_shadow;
}

