bool measured_other_owned_electronic_keyboard_octave_up_supported(const FullMixDebugCandidate &debug)
{
	if (debug.owner != InstrumentKind::Other && debug.owner != InstrumentKind::Ambiguous)
		return false;
	if (debug.midi + 12 < kKeyboardMinMidi || debug.midi + 12 > kKeyboardMaxMidi)
		return false;

	const float second = debug.harmonic_ratios[1];
	const float third = debug.harmonic_ratios[2];
	const float fourth = debug.harmonic_ratios[3];
	const float fifth = debug.harmonic_ratios[4];
	const bool existing_electronic_octave_alias =
		debug.other_score >= 0.60f &&
	       debug.guitar_score <= 0.42f &&
	       debug.keyboard_score <= 0.020f &&
	       debug.vocal_score <= 0.020f &&
	       debug.spectral_level >= 0.075f &&
	       debug.spectral_level <= 0.45f &&
	       debug.pitch_confidence >= 0.025f &&
	       debug.pitch_confidence <= 0.13f &&
	       debug.periodicity >= 0.25f &&
	       debug.periodicity <= 0.48f &&
	       debug.harmonic_fit_error >= 3.0f &&
	       debug.spectral_centroid >= 0.42f &&
	       debug.spectral_centroid <= 0.72f &&
	       second >= 4.50f &&
	       third <= 0.54f &&
	       fourth >= 8.10f &&
	       fifth <= 0.50f &&
	       debug.third_octave_ratio >= 0.985f;
	// A clean sustained organ can put the detector one octave below the
	// fundamental. This measured profile is deliberately narrow: no guitar
	// score, dominant second partial, and a present fifth all agree with the
	// electronic-keyboard octave above rather than an acoustic harmonic.
	const bool clean_high_second_organ_octave_alias =
		debug.owner == InstrumentKind::Other && debug.guitar_score <= 1.0e-6f &&
		debug.pitch_confidence >= 0.36f && debug.periodicity >= 0.72f &&
		debug.harmonic_fit_error <= 0.62f && debug.local_noise_level <= 0.18f &&
		second >= 1.60f && fifth >= 0.040f;
	return existing_electronic_octave_alias || clean_high_second_organ_octave_alias;
}

bool measured_clean_organ_keyboard_octave_up_supported(const FullMixDebugCandidate &debug)
{
	if (debug.owner != InstrumentKind::Other &&
	    debug.owner != InstrumentKind::Guitar &&
	    debug.owner != InstrumentKind::Ambiguous)
		return false;
	if (debug.midi + 12 < kKeyboardMinMidi || debug.midi + 12 > kKeyboardMaxMidi)
		return false;
	if (debug.midi < 60 || debug.midi > 84)
		return false;

	const float second = debug.harmonic_ratios[1];
	const float third = debug.harmonic_ratios[2];
	const float fourth = debug.harmonic_ratios[3];
	const float fifth = debug.harmonic_ratios[4];
	const float competing_score = std::max(debug.other_score, debug.guitar_score);
	return competing_score >= 0.40f &&
	       debug.keyboard_score <= 0.32f &&
	       debug.vocal_score <= 0.020f &&
	       debug.spectral_level >= 0.23f &&
	       debug.pitch_confidence >= 0.090f &&
	       debug.periodicity >= 0.44f &&
	       debug.harmonic_fit_error >= 0.075f &&
	       debug.harmonic_fit_error <= 1.90f &&
	       debug.local_noise_level <= 0.026f &&
	       debug.spectral_centroid >= 0.30f &&
	       debug.spectral_centroid <= 0.62f &&
	       debug.spectral_slope <= 1.60f &&
	       debug.third_octave_ratio <= 0.080f &&
	       second >= 0.35f &&
	       second <= 4.60f &&
	       third <= 3.20f &&
	       fourth <= 4.10f &&
	       fifth <= 0.25f;
}

