bool measured_acoustic_string_other_visual_restore_supported(const FullMixDebugCandidate &debug)
{
	// Two clean acoustic-string E4 fixtures retain an Other note just below a
	// guitar mirror.  Their guitar-over-vocal ownership split and absent third
	// harmonic separate them from the broad string/guitar overlap.
	return debug.owner == InstrumentKind::Guitar &&
	       debug.guitar_score >= debug.vocal_score * 2.482f &&
	       debug.harmonic_ratios[2] <= 0.011f;
}

void boost_existing_measured_acoustic_string_other_visual_notes(
	NoteGrid &other_grid, const NoteGrid &guitar_grid, const FullMixOwnership &ownership)
{
	static constexpr float kMinExistingOtherLevel = 0.50f;
	static constexpr float kVisualLead = 0.015f;
	static constexpr float kMaximumVisualFloor = 0.91f;
	const std::size_t debug_count =
		std::min<std::size_t>(ownership.debug_candidate_count, ownership.debug_candidates.size());
	for (std::size_t i = 0; i < debug_count; ++i) {
		const FullMixDebugCandidate &debug = ownership.debug_candidates[i];
		if (!measured_acoustic_string_other_visual_restore_supported(debug))
			continue;
		if (note_grid_midi_level(other_grid, debug.midi) < kMinExistingOtherLevel)
			continue;
		const float guitar_visual = note_grid_midi_visual_level(guitar_grid, debug.midi);
		const float other_visual = note_grid_midi_visual_level(other_grid, debug.midi);
		if (guitar_visual <= other_visual)
			continue;
		boost_note_grid_midi_visual_level(
			other_grid, debug.midi,
			std::min(kMaximumVisualFloor, guitar_visual + kVisualLead));
	}
}

void attenuate_ambiguous_note_cell_by_named_rows(NoteCell &cell, const NoteGrid &bass,
						 const NoteGrid &keyboard, const NoteGrid &guitar,
						 const NoteGrid &vocal, const NoteGrid &other)
{
	if (!cell.active || cell.midi < kFirstMidi || cell.midi > kLastMidi)
		return;

	const int pitch_class = midi_pitch_class(cell.midi);
	const float named_exact = std::max({
		note_grid_midi_visual_level(bass, cell.midi),
		note_grid_midi_visual_level(keyboard, cell.midi),
		note_grid_midi_visual_level(guitar, cell.midi),
		note_grid_midi_visual_level(vocal, cell.midi),
		note_grid_midi_visual_level(other, cell.midi),
	});
	const float named_pitch_class = std::max({
		note_grid_pitch_class_visual_level(bass, pitch_class),
		note_grid_pitch_class_visual_level(keyboard, pitch_class),
		note_grid_pitch_class_visual_level(guitar, pitch_class),
		note_grid_pitch_class_visual_level(vocal, pitch_class),
		note_grid_pitch_class_visual_level(other, pitch_class),
	});
	if (named_pitch_class < 0.08f)
		return;

	const float ceiling = named_exact >= 0.08f ?
				      std::max(0.02f, named_exact * 0.32f) :
				      std::max(0.02f, named_pitch_class * 0.50f);
	const float current = note_cell_effective_visual_level(cell);
	cell.visual_level = std::min(current, ceiling);
}

void attenuate_ambiguous_note_grid_by_named_rows(NoteGrid &ambiguous, const NoteGrid &bass,
						 const NoteGrid &keyboard, const NoteGrid &guitar,
						 const NoteGrid &vocal, const NoteGrid &other)
{
	for (NoteCell &cell : ambiguous.cells)
		attenuate_ambiguous_note_cell_by_named_rows(cell, bass, keyboard, guitar, vocal, other);
	for (auto &row : ambiguous.rows) {
		for (NoteCell &cell : row)
			attenuate_ambiguous_note_cell_by_named_rows(cell, bass, keyboard, guitar, vocal, other);
	}
}

void write_note_grid_cell(NoteGrid &grid, const NoteCandidate &candidate, float strongest_score, float visual_loudness)
{
	const int pitch_class = ((candidate.midi % 12) + 12) % 12;
	NoteCell cell;
	write_octave(cell.label, sizeof(cell.label), candidate.midi);
	const float ownership_scale =
		candidate.ownership_confidence <= 0.24f ? std::clamp(candidate.ownership_confidence, 0.0f, 1.0f) :
							  1.0f;
	const float raw_visual_level = strongest_score > 1.0e-6f ?
					       std::clamp(candidate.score / strongest_score * visual_loudness,
							  0.0f, 1.0f) :
					       0.0f;
	// The logical grid keeps a supported low-confidence candidate available to
	// chord and expected-row detection. Its visual_level remains attenuated so
	// a mirrored note does not dominate the rendered ownership row.
	const float level = raw_visual_level;
	if (level <= 1.0e-6f)
		return;
	cell.level = level;
	if (candidate.ownership_confidence > 0.0f && candidate.ownership_confidence <= 0.24f)
		cell.visual_level =
			raw_visual_level * std::max(ownership_scale, kLowConfidenceMirrorVisualFloor);
	cell.midi = candidate.midi;
	cell.active = true;

	for (auto &row : grid.rows) {
		if (row[pitch_class].active)
			continue;
		row[pitch_class] = cell;
		break;
	}

	if (!grid.cells[pitch_class].active || cell.level > grid.cells[pitch_class].level)
		grid.cells[pitch_class] = cell;
}

void write_note_grid_label(InstrumentState &state, const NoteGrid &grid, int preferred_root)
{
	char label[64] = {};
	const int start = preferred_root >= 0 ? preferred_root % 12 : 0;
	for (int offset = 0; offset < 12; ++offset) {
		const int pitch_class = (start + offset) % 12;
		for (const auto &row : grid.rows) {
			const NoteCell &cell = row[pitch_class];
			if (!cell.active || cell.midi < 0)
				continue;

			char note[8] = {};
			write_note(note, sizeof(note), cell.midi);
			const std::size_t used = std::strlen(label);
			const std::size_t needed = std::strlen(note) + (used > 0 ? 1 : 0);
			if (used + needed + 1 > sizeof(label))
				goto done;

			std::size_t cursor = used;
			if (cursor > 0)
				label[cursor++] = ' ';
			for (const char *p = note; *p && cursor + 1 < sizeof(label); ++p)
				label[cursor++] = *p;
			label[cursor] = '\0';
		}
	}

done:
	if (!label[0]) {
		copy_text(state.label, sizeof(state.label), "--");
		state.confidence = 0.0f;
		return;
	}

	copy_text(state.label, sizeof(state.label), label);
	float confidence = 0.0f;
	for (const NoteCell &cell : grid.cells)
		confidence = std::max(confidence, cell.level);
	state.confidence = confidence;
}

int lowest_candidate_pitch_class(const NoteCandidateList &candidates)
{
	int lowest_midi = kLastMidi + 1;
	for (const NoteCandidate &candidate : candidates) {
		if (candidate.midi >= kFirstMidi && candidate.midi <= kLastMidi)
			lowest_midi = std::min(lowest_midi, candidate.midi);
	}
	return lowest_midi <= kLastMidi ? ((lowest_midi % 12) + 12) % 12 : -1;
}

std::array<float, 12> candidate_chroma(const NoteCandidateList &candidates)
{
	std::array<float, 12> chroma = {};
	float strongest_score = 0.0f;
	for (const NoteCandidate &candidate : candidates)
		strongest_score = std::max(strongest_score, candidate.score);
	if (strongest_score <= 1.0e-6f)
		return chroma;

	for (const NoteCandidate &candidate : candidates) {
		if (candidate.midi < kFirstMidi || candidate.midi > kLastMidi)
			continue;
		const int pitch_class = ((candidate.midi % 12) + 12) % 12;
		chroma[pitch_class] =
			std::max(chroma[pitch_class], std::clamp(candidate.score / strongest_score, 0.0f, 1.0f));
	}
	return chroma;
}

void set_instrument_note_set_from_candidates(NoteGrid &grid, InstrumentState &state,
					     const NoteCandidateList &candidates, int preferred_root,
					     float energy, float rms, int max_notes, float relative_floor = 0.0f)
{
	clear_note_grid(grid);
	if (rms < kNoteRmsFloor || energy < 1.0e-5f || candidates.empty()) {
		copy_text(state.label, sizeof(state.label), "--");
		state.confidence = 0.0f;
		return;
	}

	float strongest_score = 0.0f;
	for (const NoteCandidate &candidate : candidates)
		strongest_score = std::max(strongest_score, candidate.score);
	if (strongest_score <= 1.0e-6f) {
		copy_text(state.label, sizeof(state.label), "--");
		state.confidence = 0.0f;
		return;
	}

	NoteCandidateList sorted = candidates;
	std::sort(sorted.begin(), sorted.end(), [](const NoteCandidate &a, const NoteCandidate &b) {
		if (a.score != b.score)
			return a.score > b.score;
		return a.midi < b.midi;
	});
	const float score_floor = strongest_score * std::clamp(relative_floor, 0.0f, 1.0f);
	int written = 0;
	for (const NoteCandidate &candidate : sorted) {
		if (written >= std::max(1, max_notes))
			break;
		if (candidate.score < score_floor)
			continue;
		write_note_grid_cell(grid, candidate, strongest_score, note_visual_loudness(rms));
		++written;
	}
	write_note_grid_label(state, grid, preferred_root);
}

void attenuate_note_grid_display_by_candidates(NoteGrid &grid, const NoteCandidateList &candidates)
{
	auto scale_for_midi = [&](int midi) {
		float scale = 1.0f;
		bool found = false;
		for (const NoteCandidate &candidate : candidates) {
			if (candidate.midi != midi)
				continue;
			const float candidate_scale = note_candidate_display_ownership_scale(candidate);
			if (!found || candidate_scale > scale)
				scale = candidate_scale;
			found = true;
		}
		return found ? scale : 1.0f;
	};

	auto attenuate_cell = [&](NoteCell &cell) {
		if (!cell.active || cell.midi < kFirstMidi || cell.midi > kLastMidi)
			return;
		const float candidate_visual = std::clamp(cell.level * scale_for_midi(cell.midi), 0.0f, 1.0f);
		cell.visual_level =
			cell.visual_level >= 0.0f ? std::min(cell.visual_level, candidate_visual) : candidate_visual;
	};

	for (NoteCell &cell : grid.cells)
		attenuate_cell(cell);
	for (auto &row : grid.rows) {
		for (NoteCell &cell : row)
			attenuate_cell(cell);
	}
}

void collect_note_grid_levels(const NoteGrid &grid, std::array<float, kNoteProbeCount> &levels)
{
	levels.fill(0.0f);
	for (const auto &row : grid.rows) {
		for (const NoteCell &cell : row) {
			if (!cell.active || cell.midi < kFirstMidi || cell.midi > kLastMidi)
				continue;
			levels[cell.midi - kFirstMidi] = std::max(levels[cell.midi - kFirstMidi], cell.level);
		}
	}
}

void collect_note_grid_visual_levels(const NoteGrid &grid, std::array<float, kNoteProbeCount> &levels)
{
	levels.fill(0.0f);
	for (const auto &row : grid.rows) {
		for (const NoteCell &cell : row) {
			if (!cell.active || cell.midi < kFirstMidi || cell.midi > kLastMidi)
				continue;
			levels[cell.midi - kFirstMidi] =
				std::max(levels[cell.midi - kFirstMidi], note_cell_effective_visual_level(cell));
		}
	}
}

void smooth_note_grid_envelope(NoteGrid &grid, InstrumentState &state,
			       std::array<NoteTrackingState, kNoteProbeCount> &tracking,
			       int preferred_root, float interval_seconds, int max_notes,
			       const std::array<bool, kNoteProbeCount> *new_note_midi_filter = nullptr,
			       int attack_confirm_frames = kNoteAttackConfirmFrames,
			       float immediate_confirm_floor = kNoteEnvelopeImmediateConfirmFloor,
			       float release_seconds = kNoteEnvelopeReleaseSeconds,
			       float visible_floor = kNoteEnvelopeVisibleFloor,
			       const NoteCandidateList *display_candidates = nullptr,
			       const std::array<float, kNoteProbeCount> *immediate_confirm_floors = nullptr)
{
	std::array<float, kNoteProbeCount> raw_levels = {};
	collect_note_grid_levels(grid, raw_levels);
	std::array<float, kNoteProbeCount> raw_visual_levels = {};
	collect_note_grid_visual_levels(grid, raw_visual_levels);
	std::array<float, kNoteProbeCount> raw_display_scales = {};
	std::array<bool, kNoteProbeCount> raw_display_scale_present = {};
	if (display_candidates) {
		for (const NoteCandidate &candidate : *display_candidates) {
			if (candidate.midi < kFirstMidi || candidate.midi > kLastMidi)
				continue;
			const std::size_t index = static_cast<std::size_t>(candidate.midi - kFirstMidi);
			raw_display_scales[index] =
				std::max(raw_display_scales[index],
					 note_candidate_display_ownership_scale(candidate));
			raw_display_scale_present[index] = true;
		}
	}

	const float release_step =
		std::clamp(interval_seconds, 0.01f, 1.0f) / std::max(release_seconds, 0.01f);
	for (std::size_t i = 0; i < tracking.size(); ++i) {
		NoteTrackingState &note = tracking[i];
		float raw_level = std::clamp(raw_levels[i], 0.0f, 1.0f);
		if (!note.confirmed && raw_level > 0.0f && new_note_midi_filter &&
		    !(*new_note_midi_filter)[i])
			raw_level = 0.0f;
		if (!note.confirmed && raw_level > 0.0f && raw_level < kNoteEnvelopeNewNoteFloor)
			raw_level = 0.0f;

		if (raw_level > 0.0f) {
			note.consecutive_hits = std::min(note.consecutive_hits + 1, 1000);
			note.consecutive_misses = 0;
			float display_scale =
				raw_level > 1.0e-6f ?
					std::clamp(raw_visual_levels[i] / raw_level, 0.0f, 4.0f) :
					1.0f;
			if (raw_display_scale_present[i])
				display_scale *= std::clamp(raw_display_scales[i], 0.0f, 1.0f);
			note.display_scale = std::clamp(display_scale, 0.0f, 4.0f);
			const float note_immediate_confirm_floor =
				immediate_confirm_floors ?
					std::max((*immediate_confirm_floors)[i], 0.0f) :
					immediate_confirm_floor;
			if (!note.confirmed &&
			    (note.consecutive_hits >= std::max(1, attack_confirm_frames) ||
			     raw_level >= note_immediate_confirm_floor))
				note.confirmed = true;
		} else {
			note.consecutive_hits = 0;
			note.consecutive_misses = std::min(note.consecutive_misses + 1, 1000);
		}

		if (!note.confirmed) {
			note.envelope = 0.0f;
			continue;
		}

		const float level = raw_level >= note.envelope ?
					    raw_level :
					    std::max(raw_level, note.envelope - release_step);
		note.envelope = std::clamp(level, 0.0f, 1.0f);
		if (note.envelope < visible_floor) {
			note = {};
		}
	}

	clear_note_grid(grid);
	struct TrackedDisplayCandidate {
		int midi = -1;
		float level = 0.0f;
		float display_scale = 1.0f;
		bool current = false;
	};
	FixedList<TrackedDisplayCandidate, kNoteProbeCount> candidates;
	for (int midi = kFirstMidi; midi <= kLastMidi; ++midi) {
		const std::size_t index = static_cast<std::size_t>(midi - kFirstMidi);
		const float level = tracking[index].envelope;
		if (level > 0.0f)
			candidates.push_back(
				TrackedDisplayCandidate{midi, level, tracking[index].display_scale,
							raw_levels[index] > 0.0f});
	}
	std::sort(candidates.begin(), candidates.end(),
		  [](const TrackedDisplayCandidate &a, const TrackedDisplayCandidate &b) {
			  if (a.current != b.current)
				  return a.current;
			  if (a.level != b.level)
				  return a.level > b.level;
			  return a.midi < b.midi;
		  });

	int written = 0;
	for (const TrackedDisplayCandidate &candidate : candidates) {
		write_note_grid_cell(grid, NoteCandidate{candidate.midi, candidate.level}, 1.0f, 1.0f);
		for (NoteCell &cell : grid.cells) {
			if (cell.active && cell.midi == candidate.midi)
				cell.visual_level = std::clamp(cell.level * candidate.display_scale, 0.0f, 1.0f);
		}
		for (auto &row : grid.rows) {
			for (NoteCell &cell : row) {
				if (cell.active && cell.midi == candidate.midi)
					cell.visual_level =
						std::clamp(cell.level * candidate.display_scale, 0.0f, 1.0f);
			}
		}
		if (++written >= std::max(1, max_notes))
			break;
	}

	write_note_grid_label(state, grid, preferred_root);
}

void update_note_tracking_from_levels(std::array<NoteTrackingState, kNoteProbeCount> &tracking,
				      const std::array<float, kNoteProbeCount> &raw_levels,
				      float interval_seconds,
				      int attack_confirm_frames = kNoteAttackConfirmFrames,
				      float immediate_confirm_floor = kNoteEnvelopeImmediateConfirmFloor,
				      float release_seconds = kNoteEnvelopeReleaseSeconds,
				      float visible_floor = kNoteEnvelopeVisibleFloor)
{
	const float release_step =
		std::clamp(interval_seconds, 0.01f, 1.0f) / std::max(release_seconds, 0.01f);
	for (std::size_t i = 0; i < tracking.size(); ++i) {
		NoteTrackingState &note = tracking[i];
		const float raw_level = std::clamp(raw_levels[i], 0.0f, 1.0f);

		if (raw_level > 0.0f) {
			note.consecutive_hits = std::min(note.consecutive_hits + 1, 1000);
			note.consecutive_misses = 0;
			if (!note.confirmed &&
			    (note.consecutive_hits >= std::max(1, attack_confirm_frames) ||
			     raw_level >= immediate_confirm_floor))
				note.confirmed = true;
		} else {
			note.consecutive_hits = 0;
			note.consecutive_misses = std::min(note.consecutive_misses + 1, 1000);
		}

		if (!note.confirmed) {
			note.envelope = 0.0f;
			continue;
		}

		const float level = raw_level >= note.envelope ?
					    raw_level :
					    std::max(raw_level, note.envelope - release_step);
		note.envelope = std::clamp(level, 0.0f, 1.0f);
		if (note.envelope < visible_floor)
			note = {};
	}
}

std::array<float, 12> tracked_note_chroma(const std::array<NoteTrackingState, kNoteProbeCount> &tracking)
{
	std::array<float, 12> chroma = {};
	for (int midi = kFirstMidi; midi <= kLastMidi; ++midi) {
		const NoteTrackingState &note = tracking[midi - kFirstMidi];
		if (!note.confirmed || note.envelope <= 0.0f)
			continue;
		const int pitch_class = ((midi % 12) + 12) % 12;
		chroma[pitch_class] = std::max(chroma[pitch_class], note.envelope);
	}
	return chroma;
}

void reset_note_grid_envelope(NoteGrid &grid, InstrumentState &state,
			      std::array<NoteTrackingState, kNoteProbeCount> &tracking)
{
	for (NoteTrackingState &note : tracking)
		note = {};
	clear_instrument_note_grid(grid, state);
}

std::array<float, 12> note_grid_chroma(const NoteGrid &grid)
{
	std::array<float, 12> chroma = {};
	for (const auto &row : grid.rows) {
		for (const NoteCell &cell : row) {
			if (!cell.active || cell.midi < 0)
				continue;
			const int pitch_class = ((cell.midi % 12) + 12) % 12;
			chroma[pitch_class] = std::max(chroma[pitch_class], cell.level);
		}
	}
	return chroma;
}

void merge_note_grid_chroma(std::array<float, 12> &chroma, const NoteGrid &grid, float scale = 1.0f)
{
	const float clamped_scale = std::clamp(scale, 0.0f, 1.0f);
	auto merge_cell = [&](const NoteCell &cell) {
		if (!cell.active || cell.midi < 0)
			return;
		const int pitch_class = ((cell.midi % 12) + 12) % 12;
		chroma[static_cast<std::size_t>(pitch_class)] =
			std::max(chroma[static_cast<std::size_t>(pitch_class)], cell.level * clamped_scale);
	};
	for (const NoteCell &cell : grid.cells)
		merge_cell(cell);
	for (const auto &row : grid.rows) {
		for (const NoteCell &cell : row)
			merge_cell(cell);
	}
}

std::array<float, 12> mixed_global_display_chroma(const NoteGrid &bass, const NoteGrid &keyboard,
						  const NoteGrid &guitar, const NoteGrid &vocal,
						  const NoteGrid &other, const NoteGrid &ambiguous)
{
	std::array<float, 12> chroma = {};
	merge_note_grid_chroma(chroma, bass, 0.80f);
	merge_note_grid_chroma(chroma, keyboard, 1.00f);
	merge_note_grid_chroma(chroma, guitar, 1.00f);
	merge_note_grid_chroma(chroma, other, 1.00f);
	merge_note_grid_chroma(chroma, ambiguous, 0.72f);
	merge_note_grid_chroma(chroma, vocal, 0.45f);
	return chroma;
}

int note_grid_active_pitch_class_count(const NoteGrid &grid)
{
	int count = 0;
	for (int pitch_class = 0; pitch_class < 12; ++pitch_class) {
		bool active = grid.cells[pitch_class].active;
		for (const auto &row : grid.rows)
			active = active || row[pitch_class].active;
		if (active)
			++count;
	}
	return count;
}

float note_grid_midi_level(const NoteGrid &grid, int midi);
bool promote_note_grid_primary_midi(NoteGrid &grid, int midi, float level);
bool full_mix_debug_other_fundamental_primary_supported(const FullMixOwnership &ownership, int midi);

void clear_note_grid_midi(NoteGrid &grid, int midi)
{
	if (midi < kFirstMidi || midi > kLastMidi)
		return;

	const int pitch_class = midi_pitch_class(midi);
	if (grid.cells[pitch_class].active && grid.cells[pitch_class].midi == midi)
		grid.cells[pitch_class] = {};
	for (auto &row : grid.rows) {
		if (row[pitch_class].active && row[pitch_class].midi == midi)
			row[pitch_class] = {};
	}
}

const FullMixDebugCandidate *best_same_midi_keyboard_debug(const FullMixOwnership &ownership, int midi)
{
	const FullMixDebugCandidate *best = nullptr;
	float best_score = -1.0f;
	const std::size_t debug_count =
		std::min<std::size_t>(ownership.debug_candidate_count, ownership.debug_candidates.size());
	for (std::size_t i = 0; i < debug_count; ++i) {
		const FullMixDebugCandidate &debug = ownership.debug_candidates[i];
		if (debug.midi != midi)
			continue;
		const float score = debug.keyboard_score + debug.ownership_confidence * 0.01f;
		if (!best || score > best_score) {
			best = &debug;
			best_score = score;
		}
	}
	return best;
}

float full_mix_debug_row_score(const FullMixDebugCandidate &debug, InstrumentKind row)
{
	switch (row) {
	case InstrumentKind::Guitar:
		return debug.guitar_score;
	case InstrumentKind::Keyboard:
		return debug.keyboard_score;
	case InstrumentKind::Other:
		return debug.other_score;
	case InstrumentKind::Vocal:
		return debug.vocal_score;
	case InstrumentKind::Bass:
		return debug.bass_score;
	case InstrumentKind::Ambiguous:
	default:
		return 0.0f;
	}
}

const FullMixDebugCandidate *best_same_midi_row_debug(const FullMixOwnership &ownership, int midi,
						      InstrumentKind row)
{
	const FullMixDebugCandidate *best = nullptr;
	float best_score = -1.0f;
	const std::size_t debug_count =
		std::min<std::size_t>(ownership.debug_candidate_count, ownership.debug_candidates.size());
	for (std::size_t i = 0; i < debug_count; ++i) {
		const FullMixDebugCandidate &debug = ownership.debug_candidates[i];
		if (debug.midi != midi)
			continue;
		const float score = full_mix_debug_row_score(debug, row) + debug.ownership_confidence * 0.01f;
		if (!best || score > best_score) {
			best = &debug;
			best_score = score;
		}
	}
	return best;
}

const FullMixDebugCandidate *best_same_midi_vocal_shadow_debug(const FullMixOwnership &ownership, int midi,
							       InstrumentKind owner_row)
{
	return best_same_midi_row_debug(ownership, midi, owner_row);
}

void suppress_other_dominant_same_pitch_keyboard_shadows(NoteGrid &keyboard_grid,
							 InstrumentState &keyboard_state,
							 const NoteGrid &other_grid,
							 const FullMixOwnership &ownership,
							 int preferred_root)
{
	static constexpr float kMinOtherScore = 0.24f;
	static constexpr float kMaxKeyboardToOtherScoreRatio = 0.15f;
	static constexpr float kMinKeyboardLevel = 0.25f;
	static constexpr float kMinOtherLevel = 0.25f;
	static constexpr float kMaxKeyboardToOtherLevelRatio = 0.68f;

	bool changed = false;
	for (int midi = kKeyboardMinMidi; midi <= kKeyboardMaxMidi; ++midi) {
		const float keyboard_level = note_grid_midi_visual_level(keyboard_grid, midi);
		if (keyboard_level < kMinKeyboardLevel)
			continue;
		const float other_level = note_grid_midi_visual_level(other_grid, midi);
		if (other_level < kMinOtherLevel ||
		    keyboard_level > other_level * kMaxKeyboardToOtherLevelRatio)
			continue;

		const FullMixDebugCandidate *debug = best_same_midi_keyboard_debug(ownership, midi);
		if (!debug || debug->owner == InstrumentKind::Keyboard ||
		    debug->other_score < kMinOtherScore ||
		    debug->keyboard_score > debug->other_score * kMaxKeyboardToOtherScoreRatio)
			continue;

		clear_note_grid_midi(keyboard_grid, midi);
		changed = true;
	}

	if (changed)
		write_note_grid_label(keyboard_state, keyboard_grid, preferred_root);
}

bool other_pitch_class_keyboard_shadow_supported(const FullMixDebugCandidate &debug)
{
	return debug.owner == InstrumentKind::Other &&
	       debug.other_score >= 0.70f &&
	       debug.keyboard_score <= debug.other_score * 0.25f &&
	       debug.ownership_confidence >= 0.70f &&
	       debug.pitch_confidence >= 0.30f &&
	       debug.spectral_slope >= 0.70f;
}

bool cap_keyboard_pitch_class_alias_cell(NoteCell &cell, int support_midi, float ceiling,
					 int min_alias_delta = 24,
					 bool include_lower_aliases = false,
					 bool include_exact_midi = false)
{
	if (!cell.active || cell.midi < kFirstMidi || cell.midi > kLastMidi)
		return false;
	const int delta = cell.midi - support_midi;
	const bool exact_midi = cell.midi == support_midi;
	if (exact_midi && !include_exact_midi)
		return false;
	const bool lower_alias = include_lower_aliases && delta <= -12 && delta >= -36;
	if (!exact_midi && delta < min_alias_delta && !lower_alias)
		return false;
	if (midi_pitch_class(cell.midi) != midi_pitch_class(support_midi))
		return false;
	const float current = note_cell_effective_visual_level(cell);
	if (current <= ceiling)
		return false;
	cell.level = std::min(cell.level, std::clamp(ceiling, 0.0f, 1.0f));
	cell.visual_level = ceiling;
	return true;
}

void attenuate_other_dominant_pitch_class_keyboard_shadows(NoteGrid &keyboard_grid,
							   const NoteGrid &other_grid,
							   const FullMixOwnership &ownership)
{
	static constexpr float kMinOtherVisualLevel = 0.55f;
	static constexpr float kKeyboardAliasCeilingRatio = 0.62f;

	auto process_other_cell = [&](const NoteCell &other_cell) {
		if (!other_cell.active || other_cell.midi < kFirstMidi || other_cell.midi > kLastMidi)
			return;
		const float other_level = note_cell_effective_visual_level(other_cell);
		if (other_level < kMinOtherVisualLevel)
			return;
		const FullMixDebugCandidate *debug =
			best_same_midi_row_debug(ownership, other_cell.midi, InstrumentKind::Other);
		if (!debug || !other_pitch_class_keyboard_shadow_supported(*debug))
			return;

		const float ceiling = std::max(0.04f, other_level * kKeyboardAliasCeilingRatio);
		const bool fundamental_primary =
			full_mix_debug_other_fundamental_primary_supported(ownership, other_cell.midi);
		const int min_alias_delta = fundamental_primary ? 12 : 24;
		const int pitch_class = midi_pitch_class(other_cell.midi);
		cap_keyboard_pitch_class_alias_cell(keyboard_grid.cells[static_cast<std::size_t>(pitch_class)],
						    other_cell.midi, ceiling, min_alias_delta,
						    fundamental_primary);
		for (auto &row : keyboard_grid.rows)
			cap_keyboard_pitch_class_alias_cell(row[static_cast<std::size_t>(pitch_class)],
							    other_cell.midi, ceiling, min_alias_delta,
							    fundamental_primary);
	};

	for (const NoteCell &cell : other_grid.cells)
		process_other_cell(cell);
	for (const auto &row : other_grid.rows) {
		for (const NoteCell &cell : row)
			process_other_cell(cell);
	}
}

bool measured_other_debug_pitch_class_keyboard_shadow_supported(const FullMixOwnership &ownership,
								const FullMixDebugCandidate &debug)
{
	return debug.owner == InstrumentKind::Other &&
	       debug.other_score >= 0.82f &&
	       debug.keyboard_score <= 0.12f &&
	       debug.guitar_score <= 0.25f &&
	       debug.vocal_score <= 0.08f &&
	       debug.ownership_confidence >= 0.72f &&
	       debug.pitch_confidence >= 0.025f &&
	       debug.spectral_level >= 0.10f &&
	       debug.spectral_slope >= 0.70f &&
	       full_mix_debug_other_fundamental_primary_supported(ownership, debug.midi);
}

void attenuate_measured_other_debug_pitch_class_keyboard_shadows(NoteGrid &keyboard_grid,
								InstrumentState &keyboard_state,
								const FullMixOwnership &ownership,
								int preferred_root)
{
	static constexpr float kKeyboardShadowCeilingRatio = 0.62f;

	bool changed = false;
	const std::size_t debug_count =
		std::min<std::size_t>(ownership.debug_candidate_count, ownership.debug_candidates.size());
	for (std::size_t i = 0; i < debug_count; ++i) {
		const FullMixDebugCandidate &debug = ownership.debug_candidates[i];
		if (!measured_other_debug_pitch_class_keyboard_shadow_supported(ownership, debug))
			continue;

		const float support_level =
			std::max({ownership_global_note_level(ownership, debug.midi), debug.spectral_level,
				  debug.other_score});
		const float ceiling = std::max(0.04f, support_level * kKeyboardShadowCeilingRatio);
		const int pitch_class = midi_pitch_class(debug.midi);
		changed = cap_keyboard_pitch_class_alias_cell(
				  keyboard_grid.cells[static_cast<std::size_t>(pitch_class)], debug.midi,
				  ceiling, 12, true, true) ||
			  changed;
		for (auto &row : keyboard_grid.rows) {
			changed = cap_keyboard_pitch_class_alias_cell(
					  row[static_cast<std::size_t>(pitch_class)], debug.midi,
					  ceiling, 12, true, true) ||
				  changed;
		}
	}

	if (changed)
		write_note_grid_label(keyboard_state, keyboard_grid, preferred_root);
}

bool measured_electronic_keyboard_other_visual_shadow(const FullMixDebugCandidate &debug)
{
	if (debug.owner != InstrumentKind::Other)
		return false;

	const bool sparse_organ_alias =
		debug.other_score >= 0.897f &&
		debug.local_noise_level <= 0.0020f &&
		debug.harmonic_ratios[2] <= 0.760f &&
		debug.periodicity <= 0.898f &&
		debug.pitch_confidence >= 0.670f;
	const bool measured_electronic_body =
		debug.other_score >= 0.790f &&
		debug.keyboard_score <= 0.240f &&
		debug.pitch_confidence >= 0.500f &&
		debug.periodicity >= 0.700f &&
		debug.harmonicity <= 6.500f &&
		debug.spectral_slope <= 1.150f;
	const bool weak_high_organ_octave_alias =
		debug.midi >= 77 &&
		debug.midi <= 84 &&
		debug.other_score >= 0.840f &&
		debug.keyboard_score <= 0.001f &&
		debug.vocal_score <= 0.001f &&
		debug.spectral_level <= 0.250f &&
		debug.pitch_confidence <= 0.100f &&
		debug.periodicity >= 0.200f &&
		debug.periodicity <= 0.450f &&
		debug.harmonic_fit_error >= 2.000f &&
		debug.spectral_centroid >= 0.550f &&
		debug.spectral_slope >= 0.800f &&
		debug.harmonic_ratios[1] >= 3.000f &&
		debug.harmonic_ratios[3] >= 4.000f;
	return sparse_organ_alias || measured_electronic_body || weak_high_organ_octave_alias;
}

void attenuate_measured_electronic_keyboard_other_shadows(NoteGrid &other_grid,
							  InstrumentState &other_state,
							  const NoteGrid &keyboard_grid,
							  const FullMixOwnership &ownership,
							  int preferred_root)
{
	static constexpr float kMinKeyboardPitchLevel = 0.45f;
	static constexpr float kOtherCeilingRatio = 0.86f;

	bool changed = false;
	const std::size_t debug_count =
		std::min<std::size_t>(ownership.debug_candidate_count, ownership.debug_candidates.size());
	for (std::size_t i = 0; i < debug_count; ++i) {
		const FullMixDebugCandidate &debug = ownership.debug_candidates[i];
		if (!measured_electronic_keyboard_other_visual_shadow(debug))
			continue;

		const int pitch_class = midi_pitch_class(debug.midi);
		const float keyboard_level = note_grid_pitch_class_visual_level(keyboard_grid, pitch_class);
		if (keyboard_level < kMinKeyboardPitchLevel)
			continue;

		const float other_level = note_grid_midi_visual_level(other_grid, debug.midi);
		if (other_level <= keyboard_level)
			continue;

		cap_note_grid_midi_level_and_visual_level(
			other_grid, debug.midi, std::max(0.04f, keyboard_level * kOtherCeilingRatio));
		changed = true;
	}
	if (changed)
		write_note_grid_label(other_state, other_grid, preferred_root);
}

bool low_dense_other_bass_blend_shadow_protected(const FullMixDebugCandidate &debug)
{
	if (debug.owner != InstrumentKind::Other)
		return false;
	if (debug.midi < 40 || debug.midi > 47)
		return false;

	return debug.other_score >= 0.70f &&
	       debug.guitar_score >= 0.080f &&
	       debug.guitar_score <= 0.25f &&
	       debug.keyboard_score <= 0.020f &&
	       debug.vocal_score <= 0.020f &&
	       debug.spectral_level >= 0.70f &&
	       debug.pitch_confidence >= 0.35f &&
	       debug.pitch_confidence <= 0.70f &&
	       debug.periodicity >= 0.55f &&
	       debug.periodicity <= 0.70f &&
	       debug.harmonic_fit_error >= 0.30f &&
	       debug.spectral_centroid >= 0.50f &&
	       debug.spectral_centroid <= 0.70f &&
	       debug.spectral_slope >= 1.0f &&
	       debug.local_noise_level >= 0.45f &&
	       debug.adjacent_lower_ratio >= 0.75f &&
	       debug.adjacent_upper_ratio >= 0.75f &&
	       debug.third_octave_ratio >= 0.45f &&
	       debug.harmonic_ratios[1] >= 0.70f &&
	       debug.harmonic_ratios[2] >= 0.50f &&
	       debug.harmonic_ratios[3] >= 0.70f &&
	       debug.harmonic_ratios[4] >= 0.70f;
}

void suppress_other_dominant_same_pitch_bass_shadows(NoteGrid &bass_grid, InstrumentState &bass_state,
						     const NoteGrid &other_grid,
						     const FullMixOwnership &ownership,
						     int preferred_root)
{
	static constexpr float kMinOtherScore = 0.24f;
	static constexpr float kMaxBassToOtherScoreRatio = 0.50f;
	static constexpr float kMaxBassToOtherLevelRatio = 0.66f;
	static constexpr float kMeasuredMaxBassToOtherLevelRatio = 0.94f;
	static constexpr float kGuardedMinOtherScore = 0.18f;
	static constexpr float kGuardedMaxBassToOtherScoreRatio = 0.20f;
	static constexpr float kGuardedMaxBassToOtherLevelRatio = 0.80f;
	static constexpr float kGuardedMinPitchConfidence = 0.78f;
	static constexpr float kGuardedMinPeriodicity = 0.70f;
	static constexpr float kGuardedMaxHarmonicFitError = 0.08f;
	static constexpr float kGuardedMaxNoiseLevel = 0.45f;

	bool changed = false;
	for (int midi = kBassMinMidi; midi <= kBassMaxMidi; ++midi) {
		const float bass_level = note_grid_midi_level(bass_grid, midi);
		if (bass_level <= 0.0f)
			continue;
		const float other_level = note_grid_midi_level(other_grid, midi);
		if (other_level <= 0.0f ||
		    bass_level > other_level * std::max(kMaxBassToOtherLevelRatio,
							kMeasuredMaxBassToOtherLevelRatio))
			continue;
		const FullMixDebugCandidate *debug =
			best_same_midi_row_debug(ownership, midi, InstrumentKind::Other);
		if (!debug)
			continue;
		const bool legacy_other_shadow =
			debug->other_score >= kMinOtherScore &&
			debug->bass_score <= debug->other_score * kMaxBassToOtherScoreRatio &&
			bass_level <= other_level * kGuardedMaxBassToOtherLevelRatio;
		const bool measured_owned_other_shadow =
			debug->owner == InstrumentKind::Other &&
			debug->other_score >= kMinOtherScore &&
			debug->bass_score <= debug->other_score * kMaxBassToOtherScoreRatio &&
			bass_level <= other_level * kMeasuredMaxBassToOtherLevelRatio;
		const bool guarded_other_shadow =
			debug->other_score >= kGuardedMinOtherScore &&
			debug->bass_score <= debug->other_score * kGuardedMaxBassToOtherScoreRatio &&
			bass_level <= other_level * kGuardedMaxBassToOtherLevelRatio &&
			debug->pitch_confidence >= kGuardedMinPitchConfidence &&
			debug->periodicity >= kGuardedMinPeriodicity &&
			debug->harmonic_fit_error <= kGuardedMaxHarmonicFitError &&
			debug->local_noise_level <= kGuardedMaxNoiseLevel;
		if (!legacy_other_shadow && !measured_owned_other_shadow && !guarded_other_shadow)
			continue;
		if (low_dense_other_bass_blend_shadow_protected(*debug))
			continue;

		clear_note_grid_midi(bass_grid, midi);
		changed = true;
	}
	if (changed)
		write_note_grid_label(bass_state, bass_grid, preferred_root);
}

void suppress_guitar_dominant_same_pitch_bass_shadows(NoteGrid &bass_grid, InstrumentState &bass_state,
						      const NoteGrid &guitar_grid,
						      const FullMixOwnership &ownership,
						      int preferred_root,
						      bool allow_named_guitar_source_cleanup)
{
	static constexpr float kMaxBassToGuitarLevelRatio = 0.80f;
	static constexpr float kMeasuredMinGuitarScore = 0.24f;
	static constexpr float kMeasuredMaxBassToGuitarScoreRatio = 0.15f;
	static constexpr float kMeasuredMaxBassToGuitarLevelRatio = 0.68f;
	static constexpr float kMeasuredMaxNoiseLevel = 0.60f;
	static constexpr float kNamedMinPitchConfidence = 0.78f;
	static constexpr float kNamedMinPeriodicity = 0.70f;
	static constexpr float kNamedMaxHarmonicFitError = 0.08f;

	bool changed = false;
	for (int midi = kBassMinMidi; midi <= kBassMaxMidi; ++midi) {
		const float bass_level = note_grid_midi_visual_level(bass_grid, midi);
		if (bass_level <= 0.0f)
			continue;
		const float guitar_level = note_grid_midi_visual_level(guitar_grid, midi);
		if (guitar_level <= 0.0f || bass_level > guitar_level * kMaxBassToGuitarLevelRatio)
			continue;

		bool guitar_shadow = false;
		const std::size_t debug_count =
			std::min<std::size_t>(ownership.debug_candidate_count,
					      ownership.debug_candidates.size());
		for (std::size_t i = 0; i < debug_count; ++i) {
			const FullMixDebugCandidate &debug = ownership.debug_candidates[i];
			if (debug.midi != midi || debug.owner != InstrumentKind::Guitar)
				continue;

			const bool measured_guitar_shadow =
				debug.guitar_score >= kMeasuredMinGuitarScore &&
				debug.bass_score <= debug.guitar_score * kMeasuredMaxBassToGuitarScoreRatio &&
				bass_level <= guitar_level * kMeasuredMaxBassToGuitarLevelRatio &&
				debug.local_noise_level <= kMeasuredMaxNoiseLevel;
			const bool named_guitar_shadow =
				allow_named_guitar_source_cleanup &&
				debug.guitar_score >= kMeasuredMinGuitarScore &&
				debug.bass_score <= debug.guitar_score * kMeasuredMaxBassToGuitarScoreRatio &&
				bass_level <= guitar_level * kMaxBassToGuitarLevelRatio &&
				debug.pitch_confidence >= kNamedMinPitchConfidence &&
				debug.periodicity >= kNamedMinPeriodicity &&
				debug.harmonic_fit_error <= kNamedMaxHarmonicFitError &&
				debug.local_noise_level <= kMeasuredMaxNoiseLevel;
			if (measured_guitar_shadow || named_guitar_shadow) {
				guitar_shadow = true;
				break;
			}
		}
		if (!guitar_shadow)
			continue;

		clear_note_grid_midi(bass_grid, midi);
		changed = true;
	}

	if (changed)
		write_note_grid_label(bass_state, bass_grid, preferred_root);
}

void suppress_keyboard_owned_same_pitch_bass_shadows(NoteGrid &bass_grid, InstrumentState &bass_state,
						     const NoteGrid &keyboard_grid,
						     const FullMixOwnership &ownership,
						     int preferred_root,
						     bool allow_dominant_keyboard_shadow)
{
	static constexpr float kMaxBassScore = 0.10f;
	static constexpr float kMaxBassLevel = 0.46f;
	static constexpr float kMinKeyboardScore = 0.18f;
	static constexpr float kDominantMinKeyboardScore = 0.24f;
	static constexpr float kDominantMaxBassToKeyboardScoreRatio = 0.50f;
	static constexpr float kDominantMaxBassToKeyboardLevelRatio = 0.695f;
	static constexpr float kGuardedMinKeyboardScore = 0.18f;
	static constexpr float kGuardedMaxBassToKeyboardScoreRatio = 0.20f;
	static constexpr float kGuardedMaxBassToKeyboardLevelRatio = 0.80f;
	static constexpr float kGuardedMinPitchConfidence = 0.78f;
	static constexpr float kGuardedMinPeriodicity = 0.70f;
	static constexpr float kGuardedMaxHarmonicFitError = 0.08f;
	static constexpr float kGuardedMaxNoiseLevel = 0.45f;

	bool changed = false;
	for (int midi = kBassMinMidi; midi <= kBassMaxMidi; ++midi) {
		const float bass_level = note_grid_midi_level(bass_grid, midi);
		if (bass_level <= 0.0f)
			continue;
		const float keyboard_level = note_grid_midi_level(keyboard_grid, midi);
		if (keyboard_level <= 0.0f)
			continue;

		const FullMixDebugCandidate *debug =
			best_same_midi_row_debug(ownership, midi, InstrumentKind::Keyboard);
		if (!debug || debug->owner != InstrumentKind::Keyboard)
			continue;

		const bool weak_keyboard_owned_shadow =
			bass_level <= kMaxBassLevel &&
			debug->bass_score <= kMaxBassScore &&
			debug->keyboard_score >= kMinKeyboardScore;
		const bool dominant_keyboard_owned_shadow =
			allow_dominant_keyboard_shadow &&
			full_mix_row_midi_active(ownership.keyboard, midi) &&
			debug->keyboard_score >= kDominantMinKeyboardScore &&
			debug->bass_score <= debug->keyboard_score * kDominantMaxBassToKeyboardScoreRatio &&
			bass_level <= keyboard_level * kDominantMaxBassToKeyboardLevelRatio;
		const bool guarded_keyboard_shadow =
			allow_dominant_keyboard_shadow &&
			full_mix_row_midi_active(ownership.keyboard, midi) &&
			debug->keyboard_score >= kGuardedMinKeyboardScore &&
			debug->bass_score <= debug->keyboard_score * kGuardedMaxBassToKeyboardScoreRatio &&
			bass_level <= keyboard_level * kGuardedMaxBassToKeyboardLevelRatio &&
			debug->pitch_confidence >= kGuardedMinPitchConfidence &&
			debug->periodicity >= kGuardedMinPeriodicity &&
			debug->harmonic_fit_error <= kGuardedMaxHarmonicFitError &&
			debug->local_noise_level <= kGuardedMaxNoiseLevel;
		const bool guarded_keyboard_grid_shadow =
			allow_dominant_keyboard_shadow &&
			debug->keyboard_score >= kGuardedMinKeyboardScore &&
			debug->bass_score <= debug->keyboard_score * kGuardedMaxBassToKeyboardScoreRatio &&
			bass_level <= keyboard_level * kGuardedMaxBassToKeyboardLevelRatio &&
			debug->pitch_confidence >= kGuardedMinPitchConfidence &&
			debug->periodicity >= kGuardedMinPeriodicity &&
			debug->harmonic_fit_error <= kGuardedMaxHarmonicFitError &&
			debug->local_noise_level <= kGuardedMaxNoiseLevel;
		const bool high_pure_keyboard_shadow =
			allow_dominant_keyboard_shadow &&
			midi >= 53 &&
			midi <= 59 &&
			full_mix_row_midi_active(ownership.keyboard, midi) &&
			debug->keyboard_score >= 0.98f &&
			debug->bass_score <= 0.001f &&
			debug->pitch_confidence >= 0.85f &&
			debug->periodicity >= 0.65f &&
			debug->harmonic_fit_error <= 0.060f &&
			debug->local_noise_level <= 0.160f &&
			debug->spectral_centroid <= 0.060f &&
			debug->harmonic_ratios[2] >= 0.075f &&
			debug->harmonic_ratios[3] <= 0.025f;
		if (!weak_keyboard_owned_shadow && !dominant_keyboard_owned_shadow &&
		    !guarded_keyboard_shadow && !guarded_keyboard_grid_shadow &&
		    !high_pure_keyboard_shadow)
			continue;

		clear_note_grid_midi(bass_grid, midi);
		changed = true;
	}

	if (changed)
		write_note_grid_label(bass_state, bass_grid, preferred_root);
}

void suppress_vocal_owned_same_pitch_bass_shadows(NoteGrid &bass_grid, InstrumentState &bass_state,
						  const NoteGrid &vocal_grid,
						  const FullMixOwnership &ownership,
						  int preferred_root)
{
	static constexpr float kMinVocalScore = 0.24f;
	static constexpr float kMaxBassToVocalScoreRatio = 0.50f;
	static constexpr float kMaxBassToVocalLevelRatio = 0.94f;

	bool changed = false;
	for (int midi = kBassMinMidi; midi <= kBassMaxMidi; ++midi) {
		const float bass_level = note_grid_midi_visual_level(bass_grid, midi);
		if (bass_level <= 0.0f)
			continue;
		const float vocal_level = note_grid_midi_visual_level(vocal_grid, midi);
		if (vocal_level <= 0.0f || bass_level > vocal_level * kMaxBassToVocalLevelRatio)
			continue;

		const FullMixDebugCandidate *debug =
			best_same_midi_row_debug(ownership, midi, InstrumentKind::Vocal);
		if (!debug || debug->owner != InstrumentKind::Vocal)
			continue;
		if (debug->vocal_score < kMinVocalScore ||
		    debug->bass_score > debug->vocal_score * kMaxBassToVocalScoreRatio)
			continue;

		clear_note_grid_midi(bass_grid, midi);
		changed = true;
	}

	if (changed)
		write_note_grid_label(bass_state, bass_grid, preferred_root);
}

void suppress_vocal_owned_same_pitch_non_vocal_shadows(NoteGrid &grid, InstrumentState &state,
						       const NoteGrid &vocal_grid,
						       const FullMixOwnership &ownership,
						       InstrumentKind row, int preferred_root)
{
	static constexpr float kMinVocalConfidence = 0.50f;
	static constexpr float kMaxRowToVocalScoreRatio = 0.45f;
	static constexpr float kMinVocalLevel = 0.18f;

	bool changed = false;
	for (int midi = kVocalMinMidi; midi <= kVocalMaxMidi; ++midi) {
		const float row_level = note_grid_midi_visual_level(grid, midi);
		if (row_level <= 0.0f)
			continue;
		const float vocal_level = note_grid_midi_visual_level(vocal_grid, midi);
		if (vocal_level < kMinVocalLevel)
			continue;

		const FullMixDebugCandidate *debug = full_mix_debug_for_midi(ownership, midi);
		if (!debug || debug->owner != InstrumentKind::Vocal ||
		    debug->ownership_confidence < kMinVocalConfidence)
			continue;
		if ((row == InstrumentKind::Keyboard || row == InstrumentKind::Guitar) &&
		    vocal_owned_pure_high_note_body_supported(*debug))
			continue;
		if (row == InstrumentKind::Keyboard && vocal_owned_partial_electronic_keyboard_body_supported(*debug))
			continue;
		if (row == InstrumentKind::Keyboard && vocal_owned_noisy_acoustic_keyboard_body_supported(*debug))
			continue;
		if (row == InstrumentKind::Keyboard && vocal_owned_mid_acoustic_piano_body_supported(*debug))
			continue;
		if (row == InstrumentKind::Keyboard && vocal_owned_measured_acoustic_piano_body_supported(*debug))
			continue;
		if (row == InstrumentKind::Keyboard && vocal_owned_noisy_low_electronic_keyboard_body_supported(*debug))
			continue;
		if (row == InstrumentKind::Keyboard &&
		    vocal_owned_guitar_blend_electronic_keyboard_body_supported(*debug))
			continue;
		if (row == InstrumentKind::Keyboard && vocal_owned_upper_keyboard_body_supported(*debug))
			continue;
		if (row == InstrumentKind::Keyboard && vocal_owned_high_electronic_keyboard_body_supported(*debug))
			continue;
		if (row == InstrumentKind::Guitar && vocal_owned_low_acoustic_guitar_body_supported(*debug))
			continue;
		if (row == InstrumentKind::Guitar && vocal_owned_high_partial_acoustic_guitar_body_supported(*debug))
			continue;
		if (row == InstrumentKind::Guitar && vocal_owned_upper_acoustic_guitar_body_supported(*debug))
			continue;
		if (row == InstrumentKind::Guitar && vocal_owned_sparse_electronic_guitar_body_supported(*debug))
			continue;
		if (row == InstrumentKind::Guitar && vocal_owned_mid_acoustic_guitar_body_supported(*debug))
			continue;
		if (row == InstrumentKind::Other && measured_mid_acoustic_other_body_supported(*debug))
			continue;
		if (row == InstrumentKind::Other && measured_low_acoustic_string_body_supported(*debug))
			continue;

		const float row_score = full_mix_debug_row_score(*debug, row);
		if (row_score > debug->vocal_score * kMaxRowToVocalScoreRatio)
			continue;

		clear_note_grid_midi(grid, midi);
		changed = true;
	}

	if (changed)
		write_note_grid_label(state, grid, preferred_root);
}

void suppress_named_owned_same_pitch_vocal_shadows(NoteGrid &vocal_grid, InstrumentState &vocal_state,
						   const NoteGrid &owner_grid,
						   const FullMixOwnership &ownership,
						   InstrumentKind owner_row, int preferred_root)
{
	static constexpr float kMinOwnerScore = 0.24f;
	static constexpr float kMaxVocalToOwnerScoreRatio = 0.15f;
	static constexpr float kMinVocalLevel = 0.04f;
	static constexpr float kMinOwnerLevel = 0.20f;
	static constexpr float kMaxVocalToOwnerLevelRatio = 0.72f;
	static constexpr float kMeasuredOtherMaxVocalToOwnerLevelRatio = 0.48f;
	static constexpr float kMeasuredKeyboardMaxVocalToOwnerLevelRatio = 0.48f;
	static constexpr float kWeakKeyboardOwnedMaxVocalScore = 0.10f;
	static constexpr float kWeakKeyboardOwnedMaxVocalLevel = 0.45f;
	static constexpr float kWeakKeyboardOwnedMinOwnerScore = 0.18f;

	bool changed = false;
	for (int midi = kVocalMinMidi; midi <= kVocalMaxMidi; ++midi) {
		const float vocal_level = note_grid_midi_visual_level(vocal_grid, midi);
		if (vocal_level < kMinVocalLevel)
			continue;
		const float owner_level = note_grid_midi_visual_level(owner_grid, midi);
		if (owner_level <= 0.0f)
			continue;
		if (measured_low_vocal_alias_display_midi_supported(ownership, midi))
			continue;

		const FullMixDebugCandidate *debug =
			best_same_midi_vocal_shadow_debug(ownership, midi, owner_row);
		if (!debug)
			continue;
		const float owner_score = full_mix_debug_row_score(*debug, owner_row);
		const bool weak_keyboard_owned_vocal_shadow =
			owner_row == InstrumentKind::Keyboard &&
			debug->owner == InstrumentKind::Keyboard &&
			vocal_level <= kWeakKeyboardOwnedMaxVocalLevel &&
			debug->vocal_score <= kWeakKeyboardOwnedMaxVocalScore &&
			owner_score >= kWeakKeyboardOwnedMinOwnerScore;
		if (weak_keyboard_owned_vocal_shadow) {
			clear_note_grid_midi(vocal_grid, midi);
			changed = true;
			continue;
		}
		if (owner_level < kMinOwnerLevel ||
		    vocal_level > owner_level * kMaxVocalToOwnerLevelRatio)
			continue;
		const bool owner_score_supported =
			owner_score >= kMinOwnerScore &&
			debug->vocal_score <= owner_score * kMaxVocalToOwnerScoreRatio;
		// The full-mix corpus has a compact, zero-protected-collision group where
		// a piano owns a same-pitch weak vocal display.  This stricter level ratio
		// is safe to remove even when the generic vocal-preservation guards apply.
		const bool measured_keyboard_clear_shadow =
			owner_row == InstrumentKind::Keyboard &&
			debug->owner == InstrumentKind::Keyboard &&
			owner_score_supported &&
			vocal_level <= owner_level * kMeasuredKeyboardMaxVocalToOwnerLevelRatio;
		if (measured_keyboard_clear_shadow) {
			clear_note_grid_midi(vocal_grid, midi);
			changed = true;
			continue;
		}
		const bool measured_other_owned_vocal_shadow =
			owner_row == InstrumentKind::Other &&
			debug->owner == InstrumentKind::Other &&
			owner_score_supported &&
			vocal_level <= owner_level * kMeasuredOtherMaxVocalToOwnerLevelRatio;
		const bool measured_other_clear_shadow =
			measured_other_owned_vocal_shadow &&
			measured_other_owned_vocal_shadow_suppression_supported(*debug, vocal_level,
										owner_level);
		if (!measured_other_clear_shadow &&
		    (measured_owned_formant_vocal_partial_supported(*debug) ||
		     measured_other_owned_low_confidence_vocal_partial_supported(*debug) ||
		     measured_keyboard_owned_vocal_body_supported(*debug) ||
	     measured_other_owned_harmonic_vocal_body_supported(*debug) ||
	     measured_other_owned_dense_vocal_body_supported(*debug) ||
	     measured_other_owned_rounded_vocal_body_supported(*debug) ||
	     measured_other_owned_low_d_sharp_vocal_body_supported(*debug) ||
	     measured_other_owned_low_harmonic_vocal_body_supported(*debug)))
			continue;
		if (measured_adjacent_vocal_display_supported(*debug) &&
		    !measured_other_owned_vocal_shadow)
			continue;
		if (!owner_score_supported)
			continue;

		clear_note_grid_midi(vocal_grid, midi);
		changed = true;
	}

	if (changed)
		write_note_grid_label(vocal_state, vocal_grid, preferred_root);
}

bool measured_other_owned_keyboard_shadow(const FullMixDebugCandidate &debug)
{
	return debug.owner == InstrumentKind::Other &&
	       debug.other_score >= 0.70f &&
	       debug.keyboard_score <= 0.18f &&
	       debug.spectral_centroid <= 0.552f &&
	       debug.harmonic_fit_error <= 0.784f &&
	       debug.harmonicity >= 4.814f;
}

struct LowerPitchClassVisualSupport {
	int midi = -1;
	float level = 0.0f;
};

LowerPitchClassVisualSupport strongest_lower_pitch_class_visual_support(const NoteGrid &grid, int midi)
{
	LowerPitchClassVisualSupport best;
	if (midi < kFirstMidi || midi > kLastMidi)
		return best;

	const int pitch_class = midi_pitch_class(midi);
	const int min_midi = std::max(kFirstMidi, midi - 36);
	for (int lower_midi = min_midi; lower_midi <= midi - 12; ++lower_midi) {
		if (midi_pitch_class(lower_midi) != pitch_class)
			continue;
		const float level = note_grid_midi_visual_level(grid, lower_midi);
		if (level > best.level)
			best = LowerPitchClassVisualSupport{lower_midi, level};
	}
	return best;
}

bool guitar_octave_visual_shadow_protected(const FullMixDebugCandidate &debug)
{
	return shared_guitar_pitch_display_supported(debug) ||
	       keyboard_owned_mid_acoustic_guitar_body_supported(debug) ||
	       other_owned_low_acoustic_guitar_body_supported(debug) ||
	       ambiguous_low_acoustic_guitar_body_supported(debug) ||
	       noisy_other_owned_low_acoustic_guitar_supported(debug) ||
	       other_owned_overdrive_guitar_body_supported(debug) ||
	       measured_guitar_octave_alias_supported(debug) ||
	       other_owned_distorted_guitar_octave_alias_supported(debug) ||
	       other_owned_noisy_distorted_guitar_octave_up_supported(debug);
}

bool keyboard_octave_visual_shadow_protected(const FullMixDebugCandidate &debug)
{
	return high_octave_electronic_keyboard_alias_supported(debug) ||
	       electronic_keyboard_alias_display_supported(debug) ||
	       measured_keyboard_double_octave_alias_supported(debug) ||
	       measured_low_organ_keyboard_octave_alias_supported(debug) ||
	       measured_low_pure_keyboard_octave_alias_supported(debug) ||
	       measured_pure_electronic_keyboard_ambiguous_candidate(debug) ||
	       keyboard_owned_synth_other_display_supported(debug) ||
	       keyboard_owned_string_other_display_supported(debug) ||
	       measured_keyboard_synth_other_priority_supported(debug) ||
	       measured_other_owned_electric_piano_supported(debug) ||
	       measured_other_owned_electric_piano_octave_up_supported(debug);
}

bool keyboard_octave_visual_shadow_protected_from_lower_debug(const FullMixOwnership &ownership,
							      int display_midi)
{
	const int lower_midi = display_midi - 12;
	if (lower_midi < kFirstMidi || lower_midi > kLastMidi)
		return false;
	const FullMixDebugCandidate *lower_debug = full_mix_debug_for_midi(ownership, lower_midi);
	if (!lower_debug)
		return false;
	if (lower_debug->midi + 12 != display_midi)
		return false;
	return measured_other_owned_electric_piano_octave_up_supported(*lower_debug) ||
	       measured_other_owned_electronic_keyboard_octave_up_supported(*lower_debug);
}

void attenuate_lower_non_guitar_pitch_class_guitar_octave_shadows(
	NoteGrid &guitar_grid, InstrumentState &guitar_state, const NoteGrid &keyboard_grid,
	const NoteGrid &other_grid, const FullMixOwnership &ownership, int preferred_root)
{
	static constexpr float kMinGuitarVisualLevel = 0.66f;
	static constexpr float kMinSupportVisualLevel = 0.45f;
	static constexpr float kSupportWinRatio = 0.78f;

	bool changed = false;
	for (int midi = kGuitarMinMidi; midi <= kGuitarMaxMidi; ++midi) {
		const float guitar_level = note_grid_midi_visual_level(guitar_grid, midi);
		if (guitar_level < kMinGuitarVisualLevel)
			continue;

		const FullMixDebugCandidate *debug = full_mix_debug_for_midi(ownership, midi);
		if (debug && guitar_octave_visual_shadow_protected(*debug))
			continue;

		const LowerPitchClassVisualSupport keyboard_support =
			strongest_lower_pitch_class_visual_support(keyboard_grid, midi);
		const LowerPitchClassVisualSupport other_support =
			strongest_lower_pitch_class_visual_support(other_grid, midi);
		const LowerPitchClassVisualSupport support =
			keyboard_support.level >= other_support.level ? keyboard_support : other_support;
		if (support.level < kMinSupportVisualLevel)
			continue;
		if (guitar_level <= support.level)
			continue;

		const float ceiling = std::max(0.05f, support.level * kSupportWinRatio);
		if (guitar_level <= ceiling)
			continue;
		cap_note_grid_midi_level_and_visual_level(guitar_grid, midi, ceiling);
		changed = true;
	}

	if (changed)
		write_note_grid_label(guitar_state, guitar_grid, preferred_root);
}

void attenuate_lower_other_pitch_class_keyboard_octave_shadows(NoteGrid &keyboard_grid,
							       InstrumentState &keyboard_state,
							       const NoteGrid &other_grid,
							       const FullMixOwnership &ownership,
							       int preferred_root)
{
	static constexpr float kMinKeyboardVisualLevel = 0.72f;
	static constexpr float kMinOtherSupportVisualLevel = 0.55f;
	static constexpr float kSupportWinRatio = 0.84f;

	bool changed = false;
	for (int midi = kKeyboardMinMidi; midi <= kKeyboardMaxMidi; ++midi) {
		const float keyboard_level = note_grid_midi_visual_level(keyboard_grid, midi);
		if (keyboard_level < kMinKeyboardVisualLevel)
			continue;

		const LowerPitchClassVisualSupport support =
			strongest_lower_pitch_class_visual_support(other_grid, midi);
		if (support.level < kMinOtherSupportVisualLevel)
			continue;

		const FullMixDebugCandidate *debug = full_mix_debug_for_midi(ownership, midi);
		if ((debug && keyboard_octave_visual_shadow_protected(*debug)) ||
		    keyboard_octave_visual_shadow_protected_from_lower_debug(ownership, midi))
			continue;

		const float ceiling = std::max(0.05f, support.level * kSupportWinRatio);
		if (keyboard_level <= ceiling)
			continue;
		cap_note_grid_midi_visual_level(keyboard_grid, midi, ceiling);
		changed = true;
	}

	if (changed)
		write_note_grid_label(keyboard_state, keyboard_grid, preferred_root);
}

float low_electronic_bass_alias_support_level(const FullMixOwnership &ownership, int bass_midi)
{
	if (bass_midi != 28 && bass_midi != 31)
		return 0.0f;

	const int alias_midi = bass_midi + 12;
	float support_level = 0.0f;
	const std::size_t debug_count =
		std::min<std::size_t>(ownership.debug_candidate_count, ownership.debug_candidates.size());
	for (std::size_t i = 0; i < debug_count; ++i) {
		const FullMixDebugCandidate &debug = ownership.debug_candidates[i];
		if (debug.midi != alias_midi)
			continue;
		if (debug.owner != InstrumentKind::Ambiguous || debug.ownership_confidence > 0.02f)
			continue;
		if (debug.spectral_level < 0.58f || debug.pitch_confidence < 0.46f)
			continue;
		if (debug.harmonic_ratios[3] > 0.0015f || debug.harmonic_ratios[4] > 0.030f)
			continue;
		support_level = std::max({support_level, ownership_global_note_level(ownership, alias_midi),
					  debug.spectral_level * debug.pitch_confidence});
	}
	return support_level;
}

void promote_low_electronic_bass_alias_display(NoteGrid &bass_grid, InstrumentState &bass_state,
					       const NoteGrid &keyboard_grid,
					       const FullMixOwnership &ownership, int preferred_root)
{
	static constexpr std::array<int, 2> kLowElectronicBassMidis = {28, 31};
	static constexpr float kMinFundamentalSupport = 0.035f;
	static constexpr float kMinAliasSupport = 0.45f;
	static constexpr float kPromotedVisualFloor = 0.92f;

	bool changed = false;
	for (int bass_midi : kLowElectronicBassMidis) {
		const int alias_midi = bass_midi + 12;
		const float debug_alias_support =
			low_electronic_bass_alias_support_level(ownership, bass_midi);
		if (debug_alias_support <= 0.0f)
			continue;
		const float alias_support =
			std::max(debug_alias_support, note_grid_midi_visual_level(bass_grid, alias_midi));
		if (alias_support < kMinAliasSupport)
			continue;

		const float fundamental_support =
			std::max({note_grid_midi_visual_level(bass_grid, bass_midi),
				  note_grid_midi_level(bass_grid, bass_midi),
				  note_grid_midi_visual_level(keyboard_grid, bass_midi),
				  ownership_global_note_level(ownership, bass_midi)});
		if (fundamental_support < kMinFundamentalSupport)
			continue;

		const float promoted_level =
			std::max({fundamental_support, alias_support, kPromotedVisualFloor});
		if (!promote_note_grid_primary_midi(bass_grid, bass_midi, promoted_level))
			continue;
		clear_note_grid_midi(bass_grid, alias_midi);
		changed = true;
	}

	if (changed)
		write_note_grid_label(bass_state, bass_grid, preferred_root);
}

void suppress_measured_other_owned_keyboard_shadows(NoteGrid &keyboard_grid, InstrumentState &keyboard_state,
						    const NoteGrid &other_grid,
						    const FullMixOwnership &ownership,
						    int preferred_root)
{
	static constexpr float kMinOtherPitchLevel = 0.55f;
	static constexpr float kMaxKeyboardToOtherLevelRatio = 1.35f;

	bool changed = false;
	const std::size_t debug_count =
		std::min<std::size_t>(ownership.debug_candidate_count, ownership.debug_candidates.size());
	for (std::size_t i = 0; i < debug_count; ++i) {
		const FullMixDebugCandidate &debug = ownership.debug_candidates[i];
		if (!measured_other_owned_keyboard_shadow(debug))
			continue;

		const float keyboard_level = note_grid_midi_visual_level(keyboard_grid, debug.midi);
		if (keyboard_level <= 0.0f)
			continue;
		const float other_level =
			note_grid_pitch_class_visual_level(other_grid, midi_pitch_class(debug.midi));
		if (other_level < kMinOtherPitchLevel ||
		    keyboard_level > other_level * kMaxKeyboardToOtherLevelRatio)
			continue;

		clear_note_grid_midi(keyboard_grid, debug.midi);
		changed = true;
	}

	if (changed)
		write_note_grid_label(keyboard_state, keyboard_grid, preferred_root);
}

void prune_low_synthetic_other_note_grid_harmonic_aliases(
	NoteGrid &grid, InstrumentState &state, const FullMixOwnership &ownership,
	const std::array<float, kNoteProbeCount> &powers)
{
	std::array<bool, kNoteProbeCount> active_midis = {};
	float strongest = 0.0f;
	auto collect = [&](const NoteCell &cell) {
		if (!cell.active || cell.midi < kFirstMidi || cell.midi > kLastMidi)
			return;
		active_midis[static_cast<std::size_t>(cell.midi - kFirstMidi)] = true;
		strongest = std::max(strongest, cell.level);
	};
	for (const NoteCell &cell : grid.cells)
		collect(cell);
	for (const auto &row : grid.rows) {
		for (const NoteCell &cell : row)
			collect(cell);
	}
	if (strongest <= 1.0e-6f)
		return;

	int low_fundamental = -1;
	for (int midi = kOtherMinMidi; midi <= 60; ++midi) {
		if (!active_midis[static_cast<std::size_t>(midi - kFirstMidi)])
			continue;
		const float level = note_grid_midi_level(grid, midi);
		if (level < strongest * 0.18f)
			continue;
		low_fundamental = midi;
		break;
	}
	if (low_fundamental < 0)
		return;

	// The grid can contain a quiet subharmonic candidate from the raw display
	// path. Prefer a strongly measured Other candidate above it only when the
	// lower cell has no comparable spectral support. This resolves C5 synth
	// leads/pads without allowing an upper harmonic to replace a true low root.
	float strongest_probe = 0.0f;
	for (int midi = kFirstMidi; midi <= kLastMidi; ++midi)
		strongest_probe = std::max(strongest_probe, probe_level(powers, midi));
	const std::size_t debug_count =
		std::min<std::size_t>(ownership.debug_candidate_count, ownership.debug_candidates.size());
	int supported_fundamental = -1;
	for (std::size_t i = 0; i < debug_count; ++i) {
		const FullMixDebugCandidate &debug = ownership.debug_candidates[i];
		if (debug.owner != InstrumentKind::Other || debug.midi <= low_fundamental ||
		    debug.midi > kOtherMaxMidi ||
		    !low_synthetic_other_harmonic_interval(debug.midi - low_fundamental, true))
			continue;
		const float debug_probe = probe_level(powers, debug.midi);
		const float low_probe = probe_level(powers, low_fundamental);
		if (debug.ownership_confidence < 0.72f || debug.other_score < 0.70f ||
		    debug.pitch_confidence < 0.30f || debug.periodicity < 0.55f ||
		    debug_probe < strongest_probe * 0.50f || low_probe > debug_probe * 0.15f)
			continue;
		if (supported_fundamental < 0 || debug.midi < supported_fundamental)
			supported_fundamental = debug.midi;
	}
	if (supported_fundamental >= 0)
		low_fundamental = supported_fundamental;

	int upper_aliases = 0;
	for (int midi = low_fundamental + 19; midi <= kLastMidi; ++midi) {
		if (!active_midis[static_cast<std::size_t>(midi - kFirstMidi)])
			continue;
		if (note_grid_midi_level(grid, midi) < strongest * 0.12f)
			continue;
		if (low_synthetic_other_harmonic_interval(midi - low_fundamental, false))
			++upper_aliases;
	}
	if (upper_aliases < 2)
		return;

	for (int midi = low_fundamental + 1; midi <= kLastMidi; ++midi) {
		if (!active_midis[static_cast<std::size_t>(midi - kFirstMidi)])
			continue;
		// Treat octave aliases as overtones too. This function is only called
		// for the dense synthetic-Other harmonic path, where retaining C7 for a
		// played C4 makes the display prefer the overtone over the fundamental.
		if (low_synthetic_other_harmonic_interval(midi - low_fundamental, true))
			clear_note_grid_midi(grid, midi);
	}
	write_note_grid_label(state, grid, midi_pitch_class(low_fundamental));
}

bool note_grid_has_midi(const NoteGrid &grid, int midi)
{
	if (midi < kFirstMidi || midi > kLastMidi)
		return false;
	for (const auto &row : grid.rows) {
		for (const NoteCell &cell : row) {
			if (cell.active && cell.midi == midi)
				return true;
		}
	}
	return false;
}

float note_grid_midi_level(const NoteGrid &grid, int midi)
{
	if (midi < kFirstMidi || midi > kLastMidi)
		return 0.0f;
	const int pitch_class = ((midi % 12) + 12) % 12;
	float level = 0.0f;
	if (grid.cells[pitch_class].active && grid.cells[pitch_class].midi == midi)
		level = std::max(level, grid.cells[pitch_class].level);
	for (const auto &row : grid.rows) {
		for (const NoteCell &cell : row) {
			if (cell.active && cell.midi == midi)
				level = std::max(level, cell.level);
		}
	}
	return level;
}

int note_grid_strongest_active_midi_in_range(const NoteGrid &grid, int min_midi, int max_midi)
{
	min_midi = std::max(min_midi, kFirstMidi);
	max_midi = std::min(max_midi, kLastMidi);
	int best_midi = -1;
	float best_level = -1.0f;
	auto consider = [&](const NoteCell &cell) {
		if (!cell.active || cell.midi < min_midi || cell.midi > max_midi)
			return;
		if (cell.level > best_level || (cell.level == best_level &&
						(best_midi < 0 || cell.midi < best_midi))) {
			best_level = cell.level;
			best_midi = cell.midi;
		}
	};
	for (const NoteCell &cell : grid.cells)
		consider(cell);
	for (const auto &row : grid.rows) {
		for (const NoteCell &cell : row)
			consider(cell);
	}
	return best_midi;
}

void prefer_supported_lower_octave_display(NoteGrid &grid, InstrumentState &state,
					   const std::array<float, kNoteProbeCount> &powers,
					   int min_midi, int max_promoted_midi, int preferred_root,
					   bool allow_single_row_raw_octave_support = false)
{
	min_midi = std::max(min_midi, kFirstMidi);
	max_promoted_midi = std::min(max_promoted_midi, kLastMidi);
	bool changed = false;

	for (int pitch_class = 0; pitch_class < 12; ++pitch_class) {
		FixedList<NoteCell, kNoteRowCount> active_cells;
		for (const auto &row : grid.rows) {
			const NoteCell &cell = row[pitch_class];
			if (cell.active && cell.midi >= kFirstMidi && cell.midi <= kLastMidi)
				active_cells.push_back(cell);
		}
		if (active_cells.empty())
			continue;

		const NoteCell primary = active_cells.front();
		if (primary.midi <= min_midi)
			continue;

		const float primary_raw = probe_level(powers, primary.midi);
		NoteCell promoted = {};
		for (int midi = std::min(max_promoted_midi, primary.midi - 12); midi >= min_midi; --midi) {
			if (midi_pitch_class(midi) != pitch_class)
				continue;
			const int octave_delta = primary.midi - midi;
			if (octave_delta % 12 != 0)
				continue;
			if (allow_single_row_raw_octave_support && octave_delta != 12)
				continue;

			const float visible_level = note_grid_midi_level(grid, midi);
			const float raw_level = probe_level(powers, midi);
			const bool visible_supported =
				visible_level >= std::max(0.045f, primary.level * 0.38f);
			const bool raw_supported =
				primary_raw > 1.0e-6f && raw_level >= primary_raw * 0.30f &&
				(active_cells.size() >= kNoteRowCount || allow_single_row_raw_octave_support);
			if (!visible_supported && !raw_supported)
				continue;

			const float support_score =
				std::max(visible_level, raw_supported ? primary.level : 0.0f);

			promoted = {};
			write_octave(promoted.label, sizeof(promoted.label), midi);
			promoted.level = std::max({visible_level, support_score, primary.level});
			promoted.midi = midi;
			promoted.active = true;
			break;
		}

		if (!promoted.active || active_cells.front().midi == promoted.midi)
			continue;

		std::array<NoteCell, kNoteRowCount> reordered = {};
		reordered[0] = promoted;
		std::size_t write = 1;
		std::array<bool, kNoteRowCount> used = {};
		while (write < reordered.size()) {
			std::size_t best = active_cells.size();
			for (std::size_t i = 0; i < active_cells.size(); ++i) {
				if (used[i] || active_cells[i].midi == promoted.midi)
					continue;
				if (best == active_cells.size() || active_cells[i].level > active_cells[best].level ||
				    (active_cells[i].level == active_cells[best].level &&
				     active_cells[i].midi < active_cells[best].midi))
					best = i;
			}
			if (best == active_cells.size())
				break;
			used[best] = true;
			reordered[write++] = active_cells[best];
		}

		for (std::size_t row = 0; row < grid.rows.size(); ++row)
			grid.rows[row][pitch_class] = reordered[row];
		grid.cells[pitch_class] = promoted;
		changed = true;
	}

	if (changed)
		write_note_grid_label(state, grid, preferred_root);
}

// A harmonic score can prefer a lower octave even where the direct upper
// probe remains substantial. A 30% direct-probe floor recovers the measured
// isolated brass upper-octave cases. Below D#3 the upper pitch must instead
// be at least 70% as strong, preventing normal low acoustic fundamentals from
// being promoted while retaining the measured muted-tuba G2/G3 alias.
void prefer_direct_upper_other_octave_primary(NoteGrid &grid, InstrumentState &state,
					      const std::array<float, kNoteProbeCount> &powers,
					      int preferred_root)
{
	bool changed = false;
	for (int pitch_class = 0; pitch_class < 12; ++pitch_class) {
		const NoteCell &primary = grid.cells[pitch_class];
		if (!primary.active || primary.midi < 43 || primary.midi > 83)
			continue;
		const int upper_midi = primary.midi + 12;
		if (upper_midi > kOtherMaxMidi)
			continue;
		const float lower_raw = probe_level(powers, primary.midi);
		const float upper_raw = probe_level(powers, upper_midi);
		const float relative_floor = primary.midi < 51 ? 0.70f : 0.30f;
		if (lower_raw <= 1.0e-6f || upper_raw < lower_raw * relative_floor)
			continue;
		changed = promote_note_grid_primary_midi(
				  grid, upper_midi, std::max(primary.level, upper_raw)) ||
		  changed;
	}
	if (changed)
		write_note_grid_label(state, grid, preferred_root);
}

void prefer_visible_lower_octave_primary(NoteGrid &grid, InstrumentState &state, int min_midi,
					 float relative_floor, int preferred_root,
					 float absolute_floor = 0.24f,
					 int deep_low_promotion_floor = kFirstMidi)
{
	min_midi = std::max(min_midi, kFirstMidi);
	bool changed = false;

	for (int pitch_class = 0; pitch_class < 12; ++pitch_class) {
		FixedList<NoteCell, kNoteRowCount> active_cells;
		for (const auto &row : grid.rows) {
			const NoteCell &cell = row[pitch_class];
			if (cell.active && cell.midi >= kFirstMidi && cell.midi <= kLastMidi)
				active_cells.push_back(cell);
		}
		if (active_cells.empty())
			continue;

		NoteCell lower = {};
		NoteCell primary = active_cells.front();
		const NoteCell &display = grid.cells[pitch_class];
		if (display.active && display.midi > primary.midi && display.level > primary.level)
			primary = display;
		for (const NoteCell &cell : active_cells) {
			if (cell.midi >= primary.midi || cell.midi < min_midi)
				continue;
			if (cell.midi < deep_low_promotion_floor && primary.midi - cell.midi > 12)
				continue;
			if (cell.level < std::max(absolute_floor, primary.level * relative_floor))
				continue;
			if (!lower.active || cell.midi < lower.midi) {
				lower = cell;
			}
		}
		if (!lower.active)
			continue;

		lower.level = std::max(lower.level, primary.level);
		// The promoted octave is the note the UI will actually present. Keep its
		// visual envelope in step with the selected primary so a valid lower
		// fundamental does not remain dim after promotion.
		lower.visual_level = std::max(lower.visual_level, primary.visual_level);
		std::array<NoteCell, kNoteRowCount> reordered = {};
		reordered[0] = lower;
		std::size_t write = 1;
		std::array<bool, kNoteRowCount> used = {};
		while (write < reordered.size()) {
			std::size_t best = active_cells.size();
			for (std::size_t i = 0; i < active_cells.size(); ++i) {
				if (used[i] || active_cells[i].midi == lower.midi)
					continue;
				if (best == active_cells.size() || active_cells[i].level > active_cells[best].level ||
				    (active_cells[i].level == active_cells[best].level &&
				     active_cells[i].midi < active_cells[best].midi))
					best = i;
			}
			if (best == active_cells.size())
				break;
			used[best] = true;
			reordered[write++] = active_cells[best];
		}

		for (std::size_t row = 0; row < grid.rows.size(); ++row)
			grid.rows[row][pitch_class] = reordered[row];
		grid.cells[pitch_class] = lower;
		changed = true;
	}

	if (changed)
		write_note_grid_label(state, grid, preferred_root);
}

bool promote_note_grid_primary_midi(NoteGrid &grid, int midi, float level)
{
	if (midi < kFirstMidi || midi > kLastMidi)
		return false;

	const int pitch_class = midi_pitch_class(midi);
	NoteCell promoted = {};
	write_octave(promoted.label, sizeof(promoted.label), midi);
	promoted.level = std::clamp(level, 0.0f, 1.0f);
	promoted.midi = midi;
	promoted.active = true;

	std::array<NoteCell, kNoteRowCount> reordered = {};
	reordered[0] = promoted;
	std::size_t write = 1;
	for (const auto &row : grid.rows) {
		const NoteCell &cell = row[pitch_class];
		if (!cell.active || cell.midi == promoted.midi || write >= reordered.size())
			continue;
		reordered[write++] = cell;
	}
	for (std::size_t row = 0; row < grid.rows.size(); ++row)
		grid.rows[row][pitch_class] = reordered[row];
	grid.cells[pitch_class] = promoted;
	return true;
}

void prefer_debug_supported_vocal_lower_octave_primary(NoteGrid &grid, InstrumentState &state,
						       const FullMixOwnership &ownership,
						       const std::array<float, kNoteProbeCount> &powers,
						       int min_midi, int preferred_root)
{
	min_midi = std::max(min_midi, kFirstMidi);
	bool changed = false;

	for (int pitch_class = 0; pitch_class < 12; ++pitch_class) {
		NoteCell primary = {};
		for (const auto &row : grid.rows) {
			const NoteCell &cell = row[pitch_class];
			if (cell.active && cell.midi >= kFirstMidi && cell.midi <= kLastMidi) {
				primary = cell;
				break;
			}
		}
		const NoteCell &display = grid.cells[pitch_class];
		if (display.active && display.midi >= kFirstMidi && display.midi <= kLastMidi &&
		    (!primary.active || display.level > primary.level))
			primary = display;
		if (!primary.active)
			continue;

		const int lower_midi = primary.midi - 12;
		if (lower_midi < min_midi || lower_midi > kVocalMaxMidi ||
		    midi_pitch_class(lower_midi) != pitch_class)
			continue;

		const FullMixDebugCandidate *debug = full_mix_debug_for_midi(ownership, primary.midi);
		if (!debug || debug->owner != InstrumentKind::Vocal || debug->midi != primary.midi)
			continue;
		if (debug->ownership_confidence < 0.76f || debug->vocal_score < 0.76f)
			continue;
		if (debug->keyboard_score > 0.26f || debug->guitar_score > 0.10f ||
		    debug->other_score > 0.10f || debug->bass_score > 0.10f)
			continue;
		if (debug->spectral_level < 0.80f || debug->pitch_confidence < 0.78f ||
		    debug->periodicity < 0.68f || debug->harmonic_fit_error > 0.10f ||
		    debug->local_noise_level > 0.18f)
			continue;

		const float lower_probe = probe_level(powers, lower_midi);
		const float primary_probe = probe_level(powers, primary.midi);
		const float lower_raw = ownership_global_note_level(ownership, lower_midi);
		const float lower_visible = note_grid_midi_level(grid, lower_midi);
		const float lower_support = std::max({lower_probe, lower_raw, lower_visible});
		if (lower_support < 0.20f)
			continue;
		if (primary_probe > 1.0e-6f && lower_probe < primary_probe * 0.25f &&
		    lower_raw < primary_probe * 0.25f && lower_visible < primary.level * 0.08f)
			continue;

		changed = promote_note_grid_primary_midi(
				  grid, lower_midi, std::max({primary.level, lower_support, debug->vocal_score})) ||
			  changed;
	}

	if (changed)
		write_note_grid_label(state, grid, preferred_root);
}

void promote_measured_vocal_octave_alias(NoteGrid &vocal_grid, InstrumentState &vocal_state,
						 const NoteGrid &keyboard_grid,
						 const FullMixOwnership &ownership,
						 const std::array<float, kNoteProbeCount> &powers,
						 int preferred_root)
{
	bool changed = false;
	for (int pitch_class = 0; pitch_class < 12; ++pitch_class) {
		NoteCell upper = {};
		for (const auto &row : keyboard_grid.rows) {
			const NoteCell &cell = row[pitch_class];
			if (cell.active && cell.midi >= kFirstMidi && cell.midi <= kLastMidi &&
			    (!upper.active || cell.level > upper.level ||
			     (cell.level == upper.level && cell.midi > upper.midi)))
				upper = cell;
		}
		const NoteCell &display = keyboard_grid.cells[pitch_class];
		if (display.active && display.midi >= kFirstMidi && display.midi <= kLastMidi &&
		    (!upper.active || display.level > upper.level ||
		     (display.level == upper.level && display.midi > upper.midi)))
			upper = display;
		if (!upper.active)
			continue;

		const int lower_midi = upper.midi - 12;
		if (upper.midi < 72 || upper.midi > 76 || lower_midi < kFullMixVocalMinMidi ||
		    lower_midi > kVocalMaxMidi)
			continue;
		const FullMixDebugCandidate *debug = full_mix_debug_for_midi(ownership, upper.midi);
		if (!debug || debug->owner != InstrumentKind::Keyboard || debug->midi != upper.midi ||
		    debug->ownership_confidence < 0.90f || debug->keyboard_score < 0.90f ||
		    debug->spectral_level < 0.80f || debug->pitch_confidence < 0.70f ||
		    debug->periodicity < 0.65f || debug->harmonic_fit_error < 0.05f ||
		    debug->harmonic_fit_error > 0.18f || debug->spectral_centroid < 0.25f ||
		    debug->spectral_centroid > 0.34f || debug->spectral_slope < 0.25f ||
		    debug->spectral_slope > 0.55f || debug->local_noise_level > 0.24f ||
		    debug->harmonic_ratios[1] < 0.02f || debug->harmonic_ratios[1] > 0.14f ||
		    debug->harmonic_ratios[2] < 0.02f || debug->harmonic_ratios[2] > 0.12f ||
		    debug->harmonic_ratios[3] < 0.02f || debug->harmonic_ratios[3] > 0.14f ||
		    debug->harmonic_ratios[4] < 0.18f || debug->harmonic_ratios[4] > 0.40f)
			continue;

		const float lower_support = std::max({probe_level(powers, lower_midi),
							       ownership_global_note_level(ownership, lower_midi),
							       note_grid_midi_level(keyboard_grid, lower_midi)});
		if (lower_support < 0.20f)
			continue;
		changed = promote_note_grid_primary_midi(
				  vocal_grid, lower_midi,
				  std::max({upper.level, lower_support, debug->spectral_level * 0.72f})) ||
			  changed;
	}
	if (changed)
		write_note_grid_label(vocal_state, vocal_grid, preferred_root);
}

void prefer_debug_supported_high_bass_primary(NoteGrid &grid, InstrumentState &state,
					      const FullMixOwnership &ownership,
					      const std::array<float, kNoteProbeCount> &powers,
					      int preferred_root)
{
	bool changed = false;
	const std::size_t debug_count =
		std::min<std::size_t>(ownership.debug_candidate_count, ownership.debug_candidates.size());
	for (int pitch_class = 0; pitch_class < 12; ++pitch_class) {
		NoteCell primary = {};
		for (const auto &row : grid.rows) {
			if (row[pitch_class].active) {
				primary = row[pitch_class];
				break;
			}
		}
		if (!primary.active)
			continue;

		int supported_midi = -1;
		float supported_level = 0.0f;
		for (std::size_t i = 0; i < debug_count; ++i) {
			const FullMixDebugCandidate &debug = ownership.debug_candidates[i];
			if (debug.owner != InstrumentKind::Bass || !full_mix_debug_bass_display_supported(debug))
				continue;
			if (debug.midi < 55 || debug.midi > kFullMixCleanHighSynthBassMaxMidi ||
			    debug.midi <= primary.midi || midi_pitch_class(debug.midi) != pitch_class)
				continue;

			const float high_level = probe_level(powers, debug.midi);
			const float lower_octave_level = probe_level(powers, debug.midi - 12);
			if (high_level <= 1.0e-6f || lower_octave_level >= high_level * 0.12f)
				continue;
			if (note_grid_midi_level(grid, debug.midi - 12) >= 0.55f)
				continue;

			if (supported_midi < 0 || debug.midi < supported_midi) {
				supported_midi = debug.midi;
				supported_level = std::max(primary.level,
							   ownership_global_note_level(ownership, debug.midi));
			}
		}
		if (supported_midi < 0)
			continue;
		changed = promote_note_grid_primary_midi(grid, supported_midi,
							 std::max(supported_level, primary.level)) ||
			  changed;
	}

	if (changed)
		write_note_grid_label(state, grid, preferred_root);
}

void prefer_debug_supported_mid_bass_primary(NoteGrid &grid, InstrumentState &state,
					     const FullMixOwnership &ownership, int preferred_root)
{
	bool changed = false;
	const std::size_t debug_count =
		std::min<std::size_t>(ownership.debug_candidate_count, ownership.debug_candidates.size());

	for (int pitch_class = 0; pitch_class < 12; ++pitch_class) {
		NoteCell primary = {};
		for (const auto &row : grid.rows) {
			if (row[pitch_class].active) {
				primary = row[pitch_class];
				break;
			}
		}
		if (!primary.active)
			continue;

		int supported_midi = -1;
		float supported_level = 0.0f;
		float supported_confidence = 0.0f;
		for (std::size_t i = 0; i < debug_count; ++i) {
			const FullMixDebugCandidate &debug = ownership.debug_candidates[i];
			if (debug.owner != InstrumentKind::Bass || !full_mix_debug_bass_display_supported(debug))
				continue;
			if (primary.midi >= 36 || debug.midi < 36 || debug.midi > 43 ||
			    debug.midi != primary.midi + 12 || midi_pitch_class(debug.midi) != pitch_class)
				continue;
			if (debug.ownership_confidence < 0.80f || debug.pitch_confidence > 0.32f ||
			    debug.periodicity < 0.40f)
				continue;

			const float raw_level = ownership_global_note_level(ownership, debug.midi);
			const float promote_level = std::max(raw_level, primary.level);
			if (supported_midi < 0 || debug.ownership_confidence > supported_confidence) {
				supported_midi = debug.midi;
				supported_level = promote_level;
				supported_confidence = debug.ownership_confidence;
			}
		}
		if (supported_midi < 0)
			continue;
		changed = promote_note_grid_primary_midi(grid, supported_midi,
							 std::max(supported_level, primary.level)) ||
			  changed;
	}

	if (changed)
		write_note_grid_label(state, grid, preferred_root);
}

void prefer_probe_supported_lower_bass_primary(NoteGrid &grid, InstrumentState &state,
					       const FullMixOwnership &ownership,
					       const std::array<float, kNoteProbeCount> &powers,
					       int preferred_root)
{
	bool changed = false;
	const std::size_t debug_count =
		std::min<std::size_t>(ownership.debug_candidate_count, ownership.debug_candidates.size());

	for (int pitch_class = 0; pitch_class < 12; ++pitch_class) {
		NoteCell primary = {};
		for (const auto &row : grid.rows) {
			if (row[pitch_class].active) {
				primary = row[pitch_class];
				break;
			}
		}
		if (!primary.active || ((primary.midi < 55 || primary.midi > 59) && primary.midi != 48))
			continue;

		const int lower_midi = primary.midi - 12;
		if (lower_midi < kBassMinMidi || midi_pitch_class(lower_midi) != pitch_class)
			continue;
		if (note_grid_midi_level(grid, lower_midi) >= 0.55f)
			continue;

		const float primary_probe = probe_level(powers, primary.midi);
		const float lower_probe = probe_level(powers, lower_midi);
		const bool measured_slap_c2_alias =
			primary.midi == 48 &&
			lower_probe >= primary_probe * 0.065f &&
			lower_probe <= primary_probe * 0.105f;
		const bool measured_high_alias =
			primary.midi >= 55 && primary.midi <= 59 &&
			lower_probe >= primary_probe * 0.020f &&
			lower_probe <= primary_probe * 0.18f;
		if (primary_probe <= 1.0e-6f || (!measured_high_alias && !measured_slap_c2_alias))
			continue;

		bool supported_primary = false;
		for (std::size_t i = 0; i < debug_count; ++i) {
			const FullMixDebugCandidate &debug = ownership.debug_candidates[i];
			if (debug.midi != primary.midi || debug.owner != InstrumentKind::Bass)
				continue;
			if (!full_mix_debug_bass_display_supported(debug))
				continue;
			if (measured_slap_c2_alias) {
				if (debug.ownership_confidence < 0.70f ||
				    debug.ownership_confidence > 0.76f ||
				    debug.pitch_confidence < 0.55f ||
				    debug.periodicity < 0.60f)
					continue;
			} else {
				if (debug.ownership_confidence < 0.95f || debug.pitch_confidence < 0.70f ||
				    debug.periodicity < 0.85f)
					continue;
			}
			supported_primary = true;
			break;
		}
		if (!supported_primary)
			continue;

		changed = promote_note_grid_primary_midi(grid, lower_midi, primary.level) || changed;
	}

	if (changed)
		write_note_grid_label(state, grid, preferred_root);
}

// The Iowa fortissimo sul-E double-bass pizzicato fixture has a repeatable
// E1--F#1 direct body beneath an E2--F#2 selected octave.  This is isolated
// bass-only handling: it avoids treating generic full-mix suboctave energy as
// a bass fundamental while preserving the deliberately conservative normal
// lower-octave display route above.
void prefer_low_acoustic_bass_suboctave_primary(
	NoteGrid &grid, InstrumentState &state,
	const std::array<float, kNoteProbeCount> &powers, int preferred_root)
{
	bool changed = false;
	for (int pitch_class = 0; pitch_class < 12; ++pitch_class) {
		const NoteCell &primary = grid.cells[pitch_class];
		if (!primary.active || primary.midi < 36 || primary.midi > 42)
			continue;

		const int lower_midi = primary.midi - 12;
		const float primary_probe = probe_level(powers, primary.midi);
		const float lower_probe = probe_level(powers, lower_midi);
		const float upper_fifth_probe = probe_level(powers, primary.midi + 7);
		if (primary_probe <= 1.0e-6f)
			continue;

		// Bowed acoustic bass C1--D#1 can retain only a 1--4% direct body
		// beneath the displayed C2--D#2 octave.  Keep this separate from the
		// fuller E1--F#1 plucked profile below: the narrow lower register and
		// bounded body prevent ordinary C2--D#2 notes from becoming suboctaves.
		const bool low_bowed_profile =
			primary.midi >= 36 && primary.midi <= 39 &&
			lower_probe >= primary_probe * 0.01f && lower_probe <= primary_probe * 0.04f &&
			upper_fifth_probe >= primary_probe * 0.10f;
		const bool low_plucked_profile =
			primary.midi >= 40 && primary.midi <= 42 &&
			lower_probe >= primary_probe * 0.04f && lower_probe <= primary_probe * 0.17f;
		if (!low_bowed_profile && !low_plucked_profile)
			continue;

		changed = promote_note_grid_primary_midi(grid, lower_midi, primary.level) || changed;
	}

	if (changed)
		write_note_grid_label(state, grid, preferred_root);
}

// Iowa fortissimo bass trombone D1--D#1 retains an unusually strong direct
// body beneath a displayed D2--D#2. The two-note range and high 60--90% body
// requirement prevent ordinary low partials from becoming brass fundamentals.
void prefer_low_brass_suboctave_primary(NoteGrid &grid, InstrumentState &state,
					const std::array<float, kNoteProbeCount> &powers,
					int preferred_root)
{
	bool changed = false;
	for (int pitch_class = 0; pitch_class < 12; ++pitch_class) {
		const NoteCell &primary = grid.cells[pitch_class];
		if (!primary.active || primary.midi < 38 || primary.midi > 39)
			continue;

		const int lower_midi = primary.midi - 12;
		const float primary_probe = probe_level(powers, primary.midi);
		const float lower_probe = probe_level(powers, lower_midi);
		if (primary_probe <= 1.0e-6f || lower_probe < primary_probe * 0.60f ||
		    lower_probe > primary_probe * 0.90f)
			continue;

		changed = promote_note_grid_primary_midi(grid, lower_midi, primary.level) || changed;
	}

	if (changed)
		write_note_grid_label(state, grid, preferred_root);
}

int lowest_note_grid_pitch_class(const NoteGrid &grid)
{
	int lowest_midi = kLastMidi + 1;
	for (const auto &row : grid.rows) {
		for (const NoteCell &cell : row) {
			if (cell.active && cell.midi >= kFirstMidi && cell.midi < lowest_midi)
				lowest_midi = cell.midi;
		}
	}
	return lowest_midi <= kLastMidi ? ((lowest_midi % 12) + 12) % 12 : -1;
}

NoteCandidateList note_grid_candidates(const NoteGrid &grid)
{
	NoteCandidateList candidates;
	for (const auto &row : grid.rows) {
		for (const NoteCell &cell : row) {
			if (!cell.active || cell.midi < kFirstMidi || cell.midi > kLastMidi)
				continue;
			candidates.push_back(NoteCandidate{cell.midi, cell.level});
		}
	}
	std::sort(candidates.begin(), candidates.end(), [](const NoteCandidate &a, const NoteCandidate &b) {
		if (a.midi != b.midi)
			return a.midi < b.midi;
		return a.score > b.score;
	});
	std::size_t write = 0;
	for (std::size_t read = 0; read < candidates.size(); ++read) {
		if (write > 0 && candidates[read].midi == candidates[write - 1].midi)
			continue;
		candidates[write++] = candidates[read];
	}
	candidates.count = write;
	return candidates;
}

float strongest_probe_pitch_class_level(const std::array<float, kNoteProbeCount> &powers,
						int pitch_class, int min_midi, int max_midi);
float strongest_probe_level(const std::array<float, kNoteProbeCount> &powers, int min_midi,
				  int max_midi);
bool note_grid_pitch_active(const NoteGrid &grid, int pitch_class);
float note_grid_pitch_level(const NoteGrid &grid, int pitch_class);

bool restore_supported_guitar_major_sixth_display_note(
	NoteGrid &display_grid, InstrumentState &display_state, const NoteGrid &analysis_grid,
	const std::array<float, kNoteProbeCount> &probe_powers,
	const std::array<float, kNoteProbeCount> &detection_powers, int min_midi, int max_midi,
	float rms, int preferred_root)
{
	// Real GAPS and GuitarTECH chords sometimes retain a clearly voiced major
	// triad while the display cap drops its sixth.  Restore only that one tone
	// when the wider analysis grid and both independent analyzer probes agree.
	const float strongest_probe = strongest_probe_level(probe_powers, min_midi, max_midi);
	const float strongest_detection =
		strongest_probe_level(detection_powers, min_midi, max_midi);
	if (strongest_probe <= 1.0e-6f || strongest_detection <= 1.0e-6f)
		return false;

	const NoteCandidateList analysis_candidates = note_grid_candidates(analysis_grid);
	for (int root = 0; root < 12; ++root) {
		const int third = (root + 4) % 12;
		const int fifth = (root + 7) % 12;
		const int sixth = (root + 9) % 12;
		if (!note_grid_pitch_active(display_grid, root) ||
		    !note_grid_pitch_active(display_grid, third) ||
		    !note_grid_pitch_active(display_grid, fifth) ||
		    note_grid_pitch_active(display_grid, sixth) ||
		    note_grid_pitch_level(analysis_grid, sixth) < 0.30f)
			continue;

		const float probe_level =
			strongest_probe_pitch_class_level(probe_powers, sixth, min_midi, max_midi) /
			strongest_probe;
		const float detection_level =
			strongest_probe_pitch_class_level(detection_powers, sixth, min_midi, max_midi) /
			strongest_detection;
		if (probe_level < 0.50f || detection_level < 0.60f)
			continue;

		const NoteCandidate *best = nullptr;
		for (const NoteCandidate &candidate : analysis_candidates) {
			if (midi_pitch_class(candidate.midi) != sixth)
				continue;
			if (!best || candidate.score > best->score)
				best = &candidate;
		}
		if (!best)
			continue;

		const float recovered_level =
			std::max({best->score, probe_level, detection_level});
		write_note_grid_cell(display_grid, NoteCandidate{best->midi, recovered_level}, 1.0f,
				     note_visual_loudness(rms));
		write_note_grid_label(display_state, display_grid, preferred_root);
		return true;
	}
	return false;
}

void prune_note_grid_to_chord_tones(NoteGrid &grid, InstrumentState &state, const ChordResult &chord,
				    int max_notes, int preferred_root)
{
	if (chord.root < 0 || !chord.label[0] || chord.label[0] == '-')
		return;

	int tone_count = 0;
	for (bool tone : chord.tones) {
		if (tone)
			++tone_count;
	}
	if (tone_count < 2)
		return;

	int active_tone_pitch_classes = 0;
	for (int pitch_class = 0; pitch_class < 12; ++pitch_class) {
		if (!chord.tones[pitch_class])
			continue;
		bool active = grid.cells[pitch_class].active;
		for (const auto &row : grid.rows)
			active = active || row[pitch_class].active;
		if (active)
			++active_tone_pitch_classes;
	}
	if (active_tone_pitch_classes < 3)
		return;

	int strongest_pitch_class = -1;
	float strongest_level = 0.0f;
	if (strongest_grid_pitch_class(grid, strongest_pitch_class, strongest_level) &&
	    !chord.tones[strongest_pitch_class])
		return;

	NoteCandidateList candidates;
	for (const NoteCandidate &candidate : note_grid_candidates(grid)) {
		const int pitch_class = ((candidate.midi % 12) + 12) % 12;
		if (chord.tones[pitch_class])
			candidates.push_back(candidate);
	}
	if (candidates.empty())
		return;

	std::sort(candidates.begin(), candidates.end(), [](const NoteCandidate &a, const NoteCandidate &b) {
		if (a.score != b.score)
			return a.score > b.score;
		return a.midi < b.midi;
	});

	clear_note_grid(grid);
	int written = 0;
	for (const NoteCandidate &candidate : candidates) {
		write_note_grid_cell(grid, candidate, 1.0f, 1.0f);
		if (++written >= std::max(1, max_notes))
			break;
	}
	write_note_grid_label(state, grid, preferred_root);
}

NoteCandidateList prune_adjacent_keyboard_candidates(const NoteCandidateList &notes)
{
	NoteCandidateList pruned;
	for (std::size_t i = 0; i < notes.size(); ++i) {
		bool weaker_neighbor = false;
		for (std::size_t j = 0; j < notes.size(); ++j) {
			if (i == j || std::abs(notes[i].midi - notes[j].midi) > 1)
				continue;
			if (notes[j].score > notes[i].score * 1.18f) {
				weaker_neighbor = true;
				break;
			}
		}
		if (!weaker_neighbor)
			pruned.push_back(notes[i]);
	}
	return pruned;
}

int longest_chromatic_run(const std::array<float, 12> &chroma)
{
	int longest = 0;
	int run = 0;
	for (int i = 0; i < 24; ++i) {
		if (chroma[i % 12] > 0.0f) {
			++run;
			longest = std::max(longest, run);
		} else {
			run = 0;
		}
	}
	return std::min(longest, 12);
}

bool chord_label_has_keyboard_ninth(const char *label)
{
	return label && (std::strstr(label, "9") || std::strstr(label, "add"));
}

ChordResult simplify_weak_keyboard_ninth(const std::array<float, 12> &chroma, const ChordResult &chord,
					 bool allow_extensions)
{
	if (chord.root < 0 || !chord_label_has_keyboard_ninth(chord.label))
		return chord;

	const int ninth = (chord.root + 2) % 12;
	float core_sum = 0.0f;
	int core_count = 0;
	for (int pitch_class = 0; pitch_class < 12; ++pitch_class) {
		if (!chord.tones[pitch_class] || pitch_class == ninth)
			continue;
		core_sum += chroma[pitch_class];
		++core_count;
	}

	if (core_count == 0 || chroma[ninth] >= (core_sum / static_cast<float>(core_count)) * 0.82f)
		return chord;

	std::array<float, 12> simplified_chroma = chroma;
	simplified_chroma[ninth] = 0.0f;
	const ChordResult simplified = detect_chord(simplified_chroma, chord.root, allow_extensions);
	if (simplified.root == chord.root && simplified.confidence >= 0.34f &&
	    !chord_label_has_keyboard_ninth(simplified.label))
		return simplified;

	return chord;
}

ChordResult detect_keyboard_chord_from_grid(const NoteGrid &grid, bool allow_extensions, int preferred_root = -1,
						    char *debug_reason = nullptr, std::size_t debug_reason_size = 0)
{
	static constexpr int kKeyboardHandSpanSemitones = 24;
	const NoteCandidateList notes =
		allow_extensions ? note_grid_candidates(grid) :
				   prune_adjacent_keyboard_candidates(note_grid_candidates(grid));
	ChordResult best;
	float best_score = 0.0f;
	int viable_clusters = 0;
	int template_misses = 0;
	int lower_conflicts = 0;

	for (std::size_t start = 0; start < notes.size(); ++start) {
		std::size_t last = start;
		float strongest = 0.0f;
		for (; last < notes.size(); ++last) {
			if (notes[last].midi - notes[start].midi > kKeyboardHandSpanSemitones)
				break;
			strongest = std::max(strongest, notes[last].score);
		}

		if (strongest <= 1.0e-6f)
			continue;

		std::array<float, 12> chroma = {};
		std::array<float, 12> extension_chroma = {};
		float level_sum = 0.0f;
		float extension_level_sum = 0.0f;
		int distinct_pitch_classes = 0;
		int extension_distinct_pitch_classes = 0;
		const float relative_level_floor = notes[start].midi < 40 ? 0.62f : 0.20f;
		const float extension_level_floor = allow_extensions ? 0.22f : relative_level_floor;
		for (std::size_t i = start; i < last; ++i) {
			const int pitch_class = ((notes[i].midi % 12) + 12) % 12;
			if (notes[i].score >= strongest * extension_level_floor) {
				if (extension_chroma[pitch_class] <= 0.0f)
					++extension_distinct_pitch_classes;
				extension_chroma[pitch_class] = std::max(extension_chroma[pitch_class], notes[i].score);
				extension_level_sum += notes[i].score;
			}
			if (notes[i].score >= strongest * relative_level_floor) {
				if (chroma[pitch_class] <= 0.0f)
					++distinct_pitch_classes;
				chroma[pitch_class] = std::max(chroma[pitch_class], notes[i].score);
				level_sum += notes[i].score;
			}
		}

		if (distinct_pitch_classes < 2 && extension_distinct_pitch_classes < 2)
			continue;
		++viable_clusters;

		const int cluster_root = preferred_root >= 0 && chroma[preferred_root % 12] > 0.0f ?
						 preferred_root :
						 ((notes[start].midi % 12) + 12) % 12;
		ChordResult chord;
		if (distinct_pitch_classes >= 2 && longest_chromatic_run(chroma) < 4) {
			chord = simplify_weak_keyboard_ninth(chroma,
							    detect_chord(chroma, cluster_root, allow_extensions),
							    allow_extensions);
		}
		if (allow_extensions && extension_distinct_pitch_classes >= 2 &&
		    longest_chromatic_run(extension_chroma) < 4) {
			const ChordResult extension_chord =
				simplify_weak_keyboard_ninth(extension_chroma,
							    detect_chord(extension_chroma, cluster_root,
									 allow_extensions),
							    allow_extensions);
			if (extension_chord.root >= 0 && extension_chord.confidence >= kChordConfidenceFloor &&
			    !extension_chord.uncertain && extension_chord.label[0] &&
			    extension_chord.label[0] != '-' &&
			    chord_label_has_keyboard_ninth(extension_chord.label)) {
				chord = extension_chord;
				chroma = extension_chroma;
				level_sum = extension_level_sum;
				distinct_pitch_classes = extension_distinct_pitch_classes;
			}
		}
		if (chord.root < 0) {
			++template_misses;
			continue;
		}
		bool lower_conflict = false;
		for (std::size_t i = 0; i < start; ++i) {
			if (notes[start].midi - notes[i].midi > kKeyboardHandSpanSemitones)
				continue;
			if (notes[i].score < strongest * 0.78f)
				continue;
			const int pitch_class = ((notes[i].midi % 12) + 12) % 12;
			if (!chord.tones[pitch_class]) {
				lower_conflict = true;
				break;
			}
		}
		if (lower_conflict) {
			++lower_conflicts;
			continue;
		}

		const float preferred_bonus =
			preferred_root >= 0 && chord.root == preferred_root % 12 && chroma[chord.root] > 0.0f ? 0.35f :
												  0.0f;
		const float score = chord.confidence + level_sum * 0.30f +
				    static_cast<float>(distinct_pitch_classes) * 0.10f + preferred_bonus -
				    static_cast<float>(start) * 0.02f;
		if (score > best_score) {
			best_score = score;
			best = chord;
		}
	}

	if (best.root < 0)
		copy_text(best.label, sizeof(best.label), "--");
	if (debug_reason && debug_reason_size > 0)
		std::snprintf(debug_reason, debug_reason_size, "clusters=%d templates=%d conflicts=%d selected=%d",
			      viable_clusters, template_misses, lower_conflicts, best.root >= 0 ? 1 : 0);
	return best;
}

ChordResult detect_caged_guitar_chord(const std::array<float, 12> &chroma, int preferred_root,
				      bool allow_altered = false)
{
	ChordResult best;
	float best_score = 0.0f;
	static constexpr float kToneThreshold = 0.08f;

	auto consider = [&](int root, const char *suffix, std::initializer_list<int> intervals, float priority) {
		float score = priority;
		std::array<bool, 12> tones = {};
		for (int interval : intervals) {
			const int pitch_class = (root + interval) % 12;
			const float value = chroma[pitch_class];
			if (value < kToneThreshold)
				return;
			tones[pitch_class] = true;
			score += value;
		}

		if (root == preferred_root)
			score += 0.60f;
		for (int pitch_class = 0; pitch_class < 12; ++pitch_class) {
			if (!tones[pitch_class])
				score -= chroma[pitch_class] * 0.08f;
		}

		if (score <= best_score)
			return;

		best_score = score;
		best.root = root;
		best.tones = tones;
		best.confidence = std::clamp(score / 4.2f, 0.0f, 1.0f);
		best.margin = best.confidence;
		best.uncertain = false;
		std::snprintf(best.label, sizeof(best.label), "%s%s", note_name(root), suffix);
	};

	for (int root = 0; root < 12; ++root) {
		consider(root, "", {0, 4, 7}, 0.16f);
		consider(root, "m", {0, 3, 7}, 0.16f);
		consider(root, "sus2", {0, 2, 7}, 0.12f);
		consider(root, "sus4", {0, 5, 7}, 0.12f);
		consider(root, "pow", {0, 7}, 0.04f);
		if (allow_altered) {
			consider(root, "dim", {0, 3, 6}, 0.10f);
			consider(root, "aug", {0, 4, 8}, 0.10f);
		}
	}

	if (best.root < 0)
		copy_text(best.label, sizeof(best.label), "--");
	return best;
}

bool full_mix_guitar_chord_context_debug_supported(const FullMixOwnership &ownership,
						   const FullMixDebugCandidate &debug,
						   int display_midi)
{
	if (display_midi < kGuitarMinMidi || display_midi > kGuitarMaxMidi)
		return false;
	if (full_mix_row_midi_active(ownership.guitar, display_midi))
		return false;
	if (full_mix_row_display_midi_suppressed(ownership, FullMixDisplayRow::Guitar, display_midi))
		return false;
	const bool low_chord_context_guitar_like =
		(debug.owner == InstrumentKind::Other || debug.owner == InstrumentKind::Ambiguous) &&
		display_midi >= kGuitarMinMidi &&
		display_midi <= 59 &&
		debug.spectral_level >= 0.42f &&
		debug.pitch_confidence >= 0.20f &&
		debug.periodicity >= 0.50f &&
		debug.harmonic_fit_error <= 0.95f &&
		debug.local_noise_level <= 0.95f &&
		(debug.guitar_score >= 0.10f || debug.harmonic_ratios[1] >= 0.30f ||
		 debug.spectral_slope >= 0.25f);
	if (!full_mix_display_mirror_supported(FullMixDisplayRow::Guitar, debug, display_midi) &&
	    !low_chord_context_guitar_like)
		return false;

	const bool dominant_keyboard_owner =
		debug.owner == InstrumentKind::Keyboard &&
		debug.keyboard_score >= 0.70f &&
		debug.keyboard_score >= debug.guitar_score + 0.40f;
	if (dominant_keyboard_owner && debug.spectral_level < 0.90f)
		return false;

	return true;
}

void mirror_full_mix_guitar_chord_context_candidates(FullMixOwnership &ownership)
{
	NoteCandidateList candidates;
	std::array<bool, 12> pitch_classes = {};
	std::array<bool, 12> low_pitch_classes = {};

	const std::size_t debug_count =
		std::min<std::size_t>(ownership.debug_candidate_count, ownership.debug_candidates.size());
	for (std::size_t i = 0; i < debug_count; ++i) {
		const FullMixDebugCandidate &debug = ownership.debug_candidates[i];
		const int display_midi = full_mix_display_mirror_midi(FullMixDisplayRow::Guitar, debug, ownership);
		const bool supported =
			full_mix_guitar_chord_context_debug_supported(ownership, debug, display_midi);
		if (!supported)
			continue;

		const float source_score =
			std::max({ownership_global_note_level(ownership, display_midi),
				  candidate_midi_score(ownership.ambiguous_candidates, display_midi),
				  candidate_midi_score(ownership.other_candidates, display_midi),
				  candidate_midi_score(ownership.keyboard_candidates, display_midi),
				  ownership_global_note_level(ownership, debug.midi)});
		if (source_score <= 1.0e-6f)
			continue;

		const int pitch_class = midi_pitch_class(display_midi);
		pitch_classes[static_cast<std::size_t>(pitch_class)] = true;
		if (display_midi <= 59)
			low_pitch_classes[static_cast<std::size_t>(pitch_class)] = true;

		const float confidence = 0.80f;
		bool updated = false;
		for (NoteCandidate &candidate : candidates) {
			if (candidate.midi != display_midi)
				continue;
			candidate.score = std::max(candidate.score, source_score);
			candidate.ownership_confidence = std::max(candidate.ownership_confidence, confidence);
			updated = true;
			break;
		}
		if (!updated) {
			NoteCandidate candidate;
			candidate.midi = display_midi;
			candidate.score = source_score;
			candidate.ownership_confidence = confidence;
			candidates.push_back(candidate);
		}
	}

	int pitch_class_count = 0;
	int low_pitch_class_count = 0;
	for (std::size_t i = 0; i < pitch_classes.size(); ++i) {
		if (pitch_classes[i])
			++pitch_class_count;
		if (low_pitch_classes[i])
			++low_pitch_class_count;
	}
	if (pitch_class_count < 3 || low_pitch_class_count < 2)
		return;

	const ChordResult caged =
		detect_caged_guitar_chord(candidate_chroma(candidates), lowest_candidate_pitch_class(candidates));
	if (caged.root < 0 || caged.confidence < kChordConfidenceFloor || caged.uncertain ||
	    !caged.label[0] || caged.label[0] == '-')
		return;

	float strongest = 0.0f;
	for (const NoteCandidate &candidate : candidates)
		strongest = std::max(strongest, candidate.score);
	if (strongest <= 1.0e-6f)
		return;

	for (const NoteCandidate &candidate : candidates) {
		const int pitch_class = midi_pitch_class(candidate.midi);
		if (!caged.tones[static_cast<std::size_t>(pitch_class)] &&
		    candidate.score < strongest * 0.80f)
			continue;
		add_full_mix_row_mirror(ownership.guitar, ownership.guitar_candidates, candidate, 0.74f,
					candidate.ownership_confidence);
	}
}

bool chord_label_has_guitar_extension_or_alteration(const char *label)
{
	if (!label)
		return false;
	return std::strstr(label, "7") || std::strstr(label, "9") || std::strstr(label, "6") ||
	       std::strstr(label, "add") || std::strstr(label, "aug") || std::strstr(label, "dim");
}

bool chord_label_has_exact_component(const char *label, const char *component)
{
	if (!label || !component || !*component)
		return false;
	const std::size_t component_len = std::strlen(component);
	const char *cursor = label;
	while (*cursor) {
		const char *end = std::strchr(cursor, '=');
		const std::size_t len = end ? static_cast<std::size_t>(end - cursor) : std::strlen(cursor);
		if (len == component_len && std::strncmp(cursor, component, component_len) == 0)
			return true;
		if (!end)
			break;
		cursor = end + 1;
	}
	return false;
}

bool chord_labels_share_exact_component(const char *left, const char *right)
{
	if (!left || !right || !*left || !*right)
		return false;
	const char *cursor = left;
	while (*cursor) {
		const char *end = std::strchr(cursor, '=');
		const std::size_t length = end ? static_cast<std::size_t>(end - cursor) : std::strlen(cursor);
		if (length > 0 && length < 32) {
			char component[32] = {};
			std::memcpy(component, cursor, length);
			component[length] = '\0';
			if (chord_label_has_exact_component(right, component))
				return true;
		}
		if (!end)
			break;
		cursor = end + 1;
	}
	return false;
}

bool chord_label_contains_all_components(const char *label, const char *required)
{
	if (!label || !required || !*label || !*required || label[0] == '-' || required[0] == '-')
		return false;

	const char *cursor = required;
	while (*cursor) {
		const char *end = std::strchr(cursor, '=');
		const std::size_t len = end ? static_cast<std::size_t>(end - cursor) : std::strlen(cursor);
		if (len == 0 || len >= 32)
			return false;

		char component[32] = {};
		std::memcpy(component, cursor, len);
		component[len] = '\0';
		if (!chord_label_has_exact_component(label, component))
			return false;

		if (!end)
			break;
		cursor = end + 1;
	}
	return true;
}

int chord_label_component_count(const char *label);

// Chord aliases are an unordered equivalence set.  Preserve the already
// displayed primary spelling when a later frame reports precisely the same
// components in a different order; otherwise the tracker needlessly treats
// a stable harmony as a chord switch and the UI flickers between aliases.
bool chord_labels_have_same_components(const char *lhs, const char *rhs)
{
	return chord_label_component_count(lhs) == chord_label_component_count(rhs) &&
	       chord_label_contains_all_components(lhs, rhs) &&
	       chord_label_contains_all_components(rhs, lhs);
}

int chord_label_component_count(const char *label)
{
	if (!label || !*label || label[0] == '-')
		return 0;

	int count = 0;
	const char *cursor = label;
	while (*cursor) {
		++count;
		const char *end = std::strchr(cursor, '=');
		if (!end)
			break;
		cursor = end + 1;
	}
	return count;
}

bool chord_label_has_root_component(const char *label, int root)
{
	if (!label || root < 0)
		return false;
	const char *cursor = label;
	while (*cursor) {
		const char *end = std::strchr(cursor, '=');
		const std::size_t len = end ? static_cast<std::size_t>(end - cursor) : std::strlen(cursor);
		ParsedRootChord parsed;
		if (parse_root_chord_component(cursor, len, parsed) && parsed.root == root)
			return true;
		if (!end)
			break;
		cursor = end + 1;
	}
	return false;
}

bool chord_label_has_root_third_component(const char *label, int root)
{
	if (!label || root < 0)
		return false;
	const char *cursor = label;
	while (*cursor) {
		const char *end = std::strchr(cursor, '=');
		const std::size_t len = end ? static_cast<std::size_t>(end - cursor) : std::strlen(cursor);
		ParsedRootChord parsed;
		if (parse_root_chord_component(cursor, len, parsed) && parsed.root == root &&
		    (parsed.quality == RootChordQuality::Major || parsed.quality == RootChordQuality::Minor))
			return true;
		if (!end)
			break;
		cursor = end + 1;
	}
	return false;
}

bool chord_label_has_unambiguous_root_third_component(const char *label, int root)
{
	if (!label || root < 0)
		return false;
	bool has_major = false;
	bool has_minor = false;
	const char *cursor = label;
	while (*cursor) {
		const char *end = std::strchr(cursor, '=');
		const std::size_t len = end ? static_cast<std::size_t>(end - cursor) : std::strlen(cursor);
		ParsedRootChord parsed;
		if (parse_root_chord_component(cursor, len, parsed) && parsed.root == root) {
			has_major = has_major || parsed.quality == RootChordQuality::Major;
			has_minor = has_minor || parsed.quality == RootChordQuality::Minor;
		}
		if (!end)
			break;
		cursor = end + 1;
	}
	return has_major != has_minor;
}

float note_grid_pitch_level(const NoteGrid &grid, int pitch_class)
{
	pitch_class = ((pitch_class % 12) + 12) % 12;
	float level = 0.0f;
	if (grid.cells[pitch_class].active)
		level = std::max(level, grid.cells[pitch_class].level);
	for (const auto &row : grid.rows) {
		if (row[pitch_class].active)
			level = std::max(level, row[pitch_class].level);
	}
	return level;
}

void guitar_harmonic_support_from_display(const NoteGrid &grid, int midi, int &count, float &strongest)
{
	static constexpr int kGuitarHarmonicIntervals[] = {12, 19, 24, 28, 31, 36};
	count = 0;
	strongest = 0.0f;
	for (int interval : kGuitarHarmonicIntervals) {
		const float level = note_grid_midi_level(grid, midi + interval);
		strongest = std::max(strongest, level);
		if (level >= 0.20f)
			++count;
	}
}

bool low_guitar_harmonic_primary_supported(const NoteGrid &grid, int midi)
{
	if (midi > 47)
		return false;
	int harmonic_count = 0;
	float strongest_harmonic = 0.0f;
	guitar_harmonic_support_from_display(grid, midi, harmonic_count, strongest_harmonic);
	return note_grid_midi_level(grid, midi + 12) >= 0.20f &&
	       note_grid_midi_level(grid, midi + 19) >= 0.20f &&
	       harmonic_count >= 2 &&
	       strongest_harmonic >= 0.70f;
}

bool full_mix_debug_guitar_note_supported(const FullMixOwnership &ownership, int midi)
{
	const std::size_t debug_count =
		std::min<std::size_t>(ownership.debug_candidate_count, ownership.debug_candidates.size());
	for (std::size_t i = 0; i < debug_count; ++i) {
		const FullMixDebugCandidate &debug = ownership.debug_candidates[i];
		if (debug.midi != midi)
			continue;
		if (debug.owner != InstrumentKind::Guitar || debug.guitar_score < 0.70f)
			continue;
		if (debug.ownership_confidence < 0.70f && debug.spectral_level < 0.34f)
			continue;
		const float raw_level = ownership_global_note_level(ownership, debug.midi);
		const bool confident_harmonic_body =
			debug.ownership_confidence >= 0.80f &&
			debug.other_score >= 0.70f &&
			debug.pitch_confidence <= 0.080f &&
			debug.periodicity >= 0.35f &&
			debug.harmonic_fit_error >= 1.0f;
		if (raw_level < 0.16f && debug.spectral_level < 0.30f && !confident_harmonic_body)
			continue;
		return true;
	}
	return false;
}

bool non_octave_guitar_harmonic_interval(int interval)
{
	interval = std::abs(interval);
	return interval == 19 || interval == 28 || interval == 31;
}

void prefer_confident_guitar_debug_notes_over_harmonic_aliases(NoteCandidateList &candidates,
							       const FullMixOwnership &ownership)
{
	if (candidates.empty())
		return;

	static constexpr int kFifteenFretGuitarDisplayMaxMidi = 79;
	const float strongest = std::max(strongest_candidate_score(candidates), 1.0e-6f);
	const std::size_t debug_count =
		std::min<std::size_t>(ownership.debug_candidate_count, ownership.debug_candidates.size());
	for (std::size_t i = 0; i < debug_count; ++i) {
		const FullMixDebugCandidate &debug = ownership.debug_candidates[i];
		if (debug.midi < kGuitarMinMidi || debug.midi > kFifteenFretGuitarDisplayMaxMidi)
			continue;
		if (!full_mix_debug_guitar_note_supported(ownership, debug.midi))
			continue;

		const float debug_level = ownership_global_note_level(ownership, debug.midi);
		float alias_score = 0.0f;
		for (const NoteCandidate &candidate : candidates) {
			if (candidate.midi == debug.midi)
				continue;
			if (!non_octave_guitar_harmonic_interval(candidate.midi - debug.midi))
				continue;

			const float alias_level = ownership_global_note_level(ownership, candidate.midi);
			if (debug_level < std::max(0.10f, alias_level * 0.45f) && debug.spectral_level < 0.34f)
				continue;
			alias_score = std::max(alias_score, candidate.score);
		}
		if (alias_score <= 1.0e-6f)
			continue;

		const float restored_score =
			std::max({alias_score * 1.08f, strongest * 0.42f, debug_level * strongest});
		bool exists = false;
		for (NoteCandidate &candidate : candidates) {
			if (candidate.midi != debug.midi)
				continue;
			candidate.score = std::max(candidate.score, restored_score);
			candidate.ownership_confidence = std::max(candidate.ownership_confidence, 0.78f);
			exists = true;
		}
		if (!exists) {
			NoteCandidate candidate;
			candidate.midi = debug.midi;
			candidate.score = restored_score;
			candidate.ownership_confidence = 0.78f;
			candidates.push_back(candidate);
		}
	}
}

float full_mix_debug_keyboard_note_score(const FullMixOwnership &ownership, int midi)
{
	const std::size_t debug_count =
		std::min<std::size_t>(ownership.debug_candidate_count, ownership.debug_candidates.size());
	float best = -1.0f;
	for (std::size_t i = 0; i < debug_count; ++i) {
		const FullMixDebugCandidate &debug = ownership.debug_candidates[i];
		if (debug.midi != midi)
			continue;
		const bool owned_keyboard =
			debug.owner == InstrumentKind::Keyboard &&
			debug.keyboard_score >= 0.68f;
		const bool ambiguous_electronic_keyboard =
			debug.owner == InstrumentKind::Ambiguous &&
			debug.keyboard_score >= 0.34f &&
			debug.keyboard_score >= debug.guitar_score * 0.75f &&
			debug.other_score <= 0.04f &&
			debug.vocal_score <= 0.04f &&
			debug.pitch_confidence >= 0.70f &&
			debug.periodicity >= 0.70f &&
			debug.harmonic_fit_error <= 0.35f &&
			debug.local_noise_level <= 0.32f &&
			debug.harmonic_ratios[2] >= 0.30f &&
			debug.harmonic_ratios[3] >= 0.10f;
		if (!owned_keyboard && !ambiguous_electronic_keyboard)
			continue;
		if (owned_keyboard && debug.ownership_confidence < 0.68f && debug.spectral_level < 0.28f)
			continue;
		if (ambiguous_electronic_keyboard && debug.spectral_level < 0.70f)
			continue;
		const float raw_level = ownership_global_note_level(ownership, debug.midi);
		if (raw_level < 0.08f && debug.spectral_level < 0.24f)
			continue;
		const float score = owned_keyboard ? debug.ownership_confidence :
						     std::max(0.72f, debug.keyboard_score);
		best = std::max(best, score);
	}
	return best;
}

bool full_mix_debug_keyboard_harmonic_primary_protected(const FullMixOwnership &ownership, int midi)
{
	if (midi < 43)
		return false;

	const std::size_t debug_count =
		std::min<std::size_t>(ownership.debug_candidate_count, ownership.debug_candidates.size());
	for (std::size_t i = 0; i < debug_count; ++i) {
		const FullMixDebugCandidate &debug = ownership.debug_candidates[i];
		if (debug.midi != midi || debug.owner != InstrumentKind::Keyboard)
			continue;
		if (debug.ownership_confidence < 0.86f)
			continue;
		if (debug.harmonicity >= 2.0f && debug.harmonic_fit_error >= 0.25f)
			return true;
	}
	return false;
}

float full_mix_debug_other_note_score(const FullMixOwnership &ownership, int midi)
{
	const std::size_t debug_count =
		std::min<std::size_t>(ownership.debug_candidate_count, ownership.debug_candidates.size());
	float best = -1.0f;
	for (std::size_t i = 0; i < debug_count; ++i) {
		const FullMixDebugCandidate &debug = ownership.debug_candidates[i];
		if (debug.midi != midi || debug.owner != InstrumentKind::Other)
			continue;
		if (debug.ownership_confidence < 0.80f)
			continue;
		if (debug.periodicity < 0.30f && debug.spectral_level < 0.28f)
			continue;
		const float raw_level = ownership_global_note_level(ownership, debug.midi);
		if (raw_level < 0.025f && debug.spectral_level < 0.24f)
			continue;
		best = std::max(best, debug.ownership_confidence);
	}
	return best;
}

bool full_mix_debug_other_fundamental_primary_supported(const FullMixOwnership &ownership, int midi)
{
	const std::size_t debug_count =
		std::min<std::size_t>(ownership.debug_candidate_count, ownership.debug_candidates.size());
	for (std::size_t i = 0; i < debug_count; ++i) {
		const FullMixDebugCandidate &debug = ownership.debug_candidates[i];
		if (debug.midi != midi || debug.owner != InstrumentKind::Other)
			continue;
		if (debug.ownership_confidence < 0.70f)
			continue;
		const bool fundamental_shape =
			debug.harmonicity >= 1.0f ||
			debug.harmonic_fit_error >= 0.20f ||
			debug.harmonic_ratios[1] >= 0.80f ||
			debug.local_noise_level >= 0.080f;
		if (fundamental_shape)
			return true;
	}
	return false;
}

void prefer_debug_supported_lower_other_octave_primary(NoteGrid &grid, InstrumentState &state,
						       const FullMixOwnership &ownership,
						       int min_midi, int preferred_root)
{
	min_midi = std::max(min_midi, kFirstMidi);
	bool changed = false;
	const std::size_t debug_count =
		std::min<std::size_t>(ownership.debug_candidate_count, ownership.debug_candidates.size());

	for (int pitch_class = 0; pitch_class < 12; ++pitch_class) {
		NoteCell primary = {};
		for (const auto &row : grid.rows) {
			const NoteCell &cell = row[pitch_class];
			if (cell.active) {
				primary = cell;
				break;
			}
		}
		if (!primary.active)
			continue;

		const float primary_debug_score =
			std::max(0.0f, full_mix_debug_other_note_score(ownership, primary.midi));
		int supported_midi = -1;
		float supported_level = 0.0f;
		float supported_debug_score = 0.0f;
		for (std::size_t i = 0; i < debug_count; ++i) {
			const FullMixDebugCandidate &debug = ownership.debug_candidates[i];
			if (debug.midi < min_midi || debug.midi >= primary.midi ||
			    midi_pitch_class(debug.midi) != pitch_class)
				continue;
			const float debug_score = full_mix_debug_other_note_score(ownership, debug.midi);
			if (debug_score < 0.80f || debug_score + 0.02f < primary_debug_score)
				continue;

			const float visible_level = note_grid_midi_level(grid, debug.midi);
			if (visible_level <= 0.0f)
				continue;
			const float raw_level = ownership_global_note_level(ownership, debug.midi);
			const int octave_delta = primary.midi - debug.midi;
			const bool one_octave = octave_delta <= 12;
			const bool visible_supported = visible_level >= 0.08f;
			const bool weak_visible_but_measured =
				visible_level >= 0.025f && raw_level >= 0.040f && debug.periodicity >= 0.32f;
			const bool deep_low_supported =
				octave_delta <= 24 && debug.midi >= 40 && visible_level >= 0.50f &&
				raw_level >= 0.30f && debug_score >= 0.90f && debug.periodicity >= 0.55f;
			if (!(one_octave && (visible_supported || weak_visible_but_measured)) &&
			    !deep_low_supported)
				continue;

			const float score = std::max(visible_level, raw_level);
			if (supported_midi < 0 || debug_score > supported_debug_score ||
			    (debug_score == supported_debug_score && score > supported_level) ||
			    (debug_score == supported_debug_score && score == supported_level &&
			     debug.midi < supported_midi)) {
				supported_midi = debug.midi;
				supported_level = score;
				supported_debug_score = debug_score;
			}
		}
		if (supported_midi < 0 || supported_midi == primary.midi)
			continue;
		changed = promote_note_grid_primary_midi(grid, supported_midi,
							 std::max(supported_level, primary.level)) ||
			  changed;
	}

	if (changed)
		write_note_grid_label(state, grid, preferred_root);
}

NoteCell note_grid_primary_cell_for_pitch_class(const NoteGrid &grid, int pitch_class)
{
	pitch_class = ((pitch_class % 12) + 12) % 12;
	for (const auto &row : grid.rows) {
		const NoteCell &cell = row[pitch_class];
		if (cell.active && cell.midi >= kFirstMidi && cell.midi <= kLastMidi &&
		    midi_pitch_class(cell.midi) == pitch_class)
			return cell;
	}
	const NoteCell &cell = grid.cells[pitch_class];
	if (cell.active && cell.midi >= kFirstMidi && cell.midi <= kLastMidi &&
	    midi_pitch_class(cell.midi) == pitch_class)
		return cell;
	return {};
}

void promote_source_hinted_other_debug_primaries(NoteGrid &grid, InstrumentState &state,
						 const FullMixOwnership &ownership,
						 const std::array<float, kNoteProbeCount> &powers,
						 int min_midi, int preferred_root,
						 bool allow_probe_lower_octave,
						 bool allow_independent_fundamental)
{
	min_midi = std::max(min_midi, kFirstMidi);
	float strongest_probe = 0.0f;
	for (int midi = kFirstMidi; midi <= kLastMidi; ++midi)
		strongest_probe = std::max(strongest_probe, probe_level(powers, midi));
	if (strongest_probe <= 1.0e-6f)
		return;

	std::array<int, 12> promoted_midis = {};
	std::array<float, 12> promoted_levels = {};
	promoted_midis.fill(-1);

	auto consider = [&](int midi, float level, bool prefer_lowest) {
		if (midi < min_midi || midi > kOtherMaxMidi)
			return;
		const int pitch_class = midi_pitch_class(midi);
		if (promoted_midis[pitch_class] < 0 ||
		    (prefer_lowest ? midi < promoted_midis[pitch_class] :
				     midi > promoted_midis[pitch_class]) ||
		    (midi == promoted_midis[pitch_class] && level > promoted_levels[pitch_class])) {
			promoted_midis[pitch_class] = midi;
			promoted_levels[pitch_class] = std::clamp(level, 0.0f, 1.0f);
		}
	};

	const std::size_t debug_count =
		std::min<std::size_t>(ownership.debug_candidate_count, ownership.debug_candidates.size());
	for (std::size_t i = 0; i < debug_count; ++i) {
		const FullMixDebugCandidate &debug = ownership.debug_candidates[i];
		if (debug.owner != InstrumentKind::Other || debug.midi < min_midi ||
		    debug.midi > kOtherMaxMidi)
			continue;
		if (debug.ownership_confidence < 0.72f || debug.other_score < 0.70f)
			continue;
		if (debug.periodicity < 0.30f && debug.pitch_confidence < 0.030f &&
		    debug.spectral_level < 0.080f)
			continue;

		const int pitch_class = midi_pitch_class(debug.midi);
		const NoteCell primary = note_grid_primary_cell_for_pitch_class(grid, pitch_class);
		if (primary.active && debug.midi < primary.midi) {
			const float debug_level = std::max(ownership_global_note_level(ownership, debug.midi),
						  debug.spectral_level);
			consider(debug.midi, std::max({primary.level, debug_level, debug.other_score}), true);
		}

		// A source-hinted synthetic tone can leave a low, display-only
		// subharmonic in the grid even when the measured debug candidate has the
		// actual fundamental. Promote the lowest strongly probed debug candidate
		// only when it decisively outweighs that lower cell; this preserves true
		// low fundamentals while recovering high synth leads and pads.
		const float dominant_debug_probe = probe_level(powers, debug.midi);
		const float dominant_primary_probe =
			primary.active ? probe_level(powers, primary.midi) : 0.0f;
		const bool dominant_source_hinted_debug_primary =
			allow_probe_lower_octave && primary.active && debug.midi > primary.midi &&
			debug.midi - primary.midi >= 24 && debug.ownership_confidence >= 0.72f &&
			debug.other_score >= 0.70f && debug.pitch_confidence >= 0.30f &&
			debug.periodicity >= 0.55f && dominant_debug_probe >= strongest_probe * 0.50f &&
			dominant_primary_probe <= dominant_debug_probe * 0.15f;
		if (dominant_source_hinted_debug_primary) {
			const float debug_level = std::max(ownership_global_note_level(ownership, debug.midi),
						  debug.spectral_level);
			consider(debug.midi, std::max({primary.level, debug_level, debug.other_score, 0.85f}),
				 true);
		}

		const bool source_hinted_exact_debug_primary =
			(allow_probe_lower_octave || allow_independent_fundamental) &&
			!primary.active &&
			debug.pitch_confidence >= 0.30f &&
			debug.periodicity >= 0.55f;
		if (source_hinted_exact_debug_primary) {
			const float debug_level = std::max(ownership_global_note_level(ownership, debug.midi),
							  debug.spectral_level);
			consider(debug.midi,
				 std::max({debug_level, debug.other_score, debug.pitch_confidence, 0.72f}),
				 allow_independent_fundamental);
		}

		const bool independent_string_fundamental =
			allow_independent_fundamental &&
			!primary.active &&
			debug.other_score >= 0.80f &&
			debug.keyboard_score <= 0.20f &&
			debug.guitar_score <= 0.25f &&
			debug.vocal_score <= 0.05f &&
			debug.spectral_level >= 0.12f &&
			debug.pitch_confidence >= 0.12f &&
			debug.periodicity >= 0.40f;
		if (independent_string_fundamental) {
			const float debug_level = std::max(ownership_global_note_level(ownership, debug.midi),
							  debug.spectral_level);
			consider(debug.midi, std::max({debug_level, debug.other_score, 0.80f}), false);
		}

		if (!allow_probe_lower_octave)
			continue;
		const int lower_midi = debug.midi - 12;
		if (lower_midi < min_midi || midi_pitch_class(lower_midi) != pitch_class)
			continue;
		const float debug_probe = probe_level(powers, debug.midi);
		const float lower_probe = probe_level(powers, lower_midi);
		const float source_hint_probe_floor = allow_independent_fundamental ? 0.030f : 0.080f;
		const float source_hint_debug_probe_floor = allow_independent_fundamental ? 0.080f : 0.20f;
		const bool lower_probe_supported =
			lower_probe >= strongest_probe * source_hint_probe_floor &&
			(debug_probe <= 1.0e-6f || lower_probe >= debug_probe * source_hint_debug_probe_floor);
		if (!lower_probe_supported)
			continue;
		const float normalized = std::clamp(lower_probe / strongest_probe, 0.0f, 1.0f);
		consider(lower_midi, std::max({normalized, debug.other_score, 0.72f}), true);
	}

	bool changed = false;
	for (int pitch_class = 0; pitch_class < 12; ++pitch_class) {
		if (promoted_midis[pitch_class] < 0)
			continue;
		changed = promote_note_grid_primary_midi(grid, promoted_midis[pitch_class],
							 promoted_levels[pitch_class]) ||
			  changed;
	}
	if (changed)
		write_note_grid_label(state, grid, preferred_root);
}

void boost_measured_other_fundamental_display_level(NoteGrid &grid, InstrumentState &state,
						    const FullMixOwnership &ownership,
						    int preferred_root)
{
	bool changed = false;
	const std::size_t debug_count =
		std::min<std::size_t>(ownership.debug_candidate_count, ownership.debug_candidates.size());
	for (std::size_t i = 0; i < debug_count; ++i) {
		const FullMixDebugCandidate &debug = ownership.debug_candidates[i];
		if (debug.owner != InstrumentKind::Other || debug.midi < kOtherMinMidi ||
		    debug.midi > kOtherMaxMidi)
			continue;
		if (debug.other_score < 0.78f ||
		    debug.keyboard_score > 0.20f ||
		    debug.guitar_score > 0.25f ||
		    debug.vocal_score > 0.08f ||
		    debug.ownership_confidence < 0.72f ||
		    !full_mix_debug_other_fundamental_primary_supported(ownership, debug.midi))
			continue;

		const float visible_level = note_grid_midi_level(grid, debug.midi);
		if (visible_level <= 0.0f || visible_level >= 0.72f)
			continue;
		const float raw_level = ownership_global_note_level(ownership, debug.midi);
		const float promoted_level =
			std::max({visible_level, raw_level, std::min(debug.other_score, 0.78f)});
		changed = promote_note_grid_primary_midi(grid, debug.midi, promoted_level) || changed;
	}
	if (changed)
		write_note_grid_label(state, grid, preferred_root);
}

void prefer_strong_visible_lower_other_octave_primary(NoteGrid &grid, InstrumentState &state,
						      int min_midi, int preferred_root)
{
	min_midi = std::max(min_midi, kFirstMidi);
	bool changed = false;

	for (int pitch_class = 0; pitch_class < 12; ++pitch_class) {
		NoteCell primary = {};
		for (const auto &row : grid.rows) {
			const NoteCell &cell = row[pitch_class];
			if (cell.active && cell.midi >= kFirstMidi && cell.midi <= kLastMidi) {
				primary = cell;
				break;
			}
		}
		if (!primary.active) {
			const NoteCell &cell = grid.cells[pitch_class];
			if (cell.active && cell.midi >= kFirstMidi && cell.midi <= kLastMidi)
				primary = cell;
		}
		if (!primary.active)
			continue;

		NoteCell lower = {};
		auto consider = [&](const NoteCell &cell) {
			if (!cell.active || cell.midi < min_midi || cell.midi >= primary.midi ||
			    cell.midi > kLastMidi || midi_pitch_class(cell.midi) != pitch_class)
				return;
			const int octave_delta = primary.midi - cell.midi;
			if (octave_delta > 12 || cell.level < 0.60f)
				return;
			if (!lower.active || cell.midi < lower.midi ||
			    (cell.midi == lower.midi && cell.level > lower.level))
				lower = cell;
		};

		consider(grid.cells[pitch_class]);
		for (const auto &row : grid.rows)
			consider(row[pitch_class]);

		if (!lower.active)
			continue;
		changed = promote_note_grid_primary_midi(grid, lower.midi,
							 std::max(lower.level, primary.level)) ||
			  changed;
	}

	if (changed)
		write_note_grid_label(state, grid, preferred_root);
}

void prefer_probe_supported_lower_synth_primary(NoteGrid &grid, InstrumentState &state,
						const FullMixOwnership &ownership,
						const std::array<float, kNoteProbeCount> &powers,
						int min_midi, int preferred_root)
{
	min_midi = std::max(min_midi, kFirstMidi);
	bool changed = false;
	const std::size_t debug_count =
		std::min<std::size_t>(ownership.debug_candidate_count, ownership.debug_candidates.size());

	for (int pitch_class = 0; pitch_class < 12; ++pitch_class) {
		NoteCell primary = {};
		for (const auto &row : grid.rows) {
			const NoteCell &cell = row[pitch_class];
			if (cell.active && cell.midi >= kFirstMidi && cell.midi <= kLastMidi) {
				primary = cell;
				break;
			}
		}
		if (!primary.active) {
			const NoteCell &cell = grid.cells[pitch_class];
			if (cell.active && cell.midi >= kFirstMidi && cell.midi <= kLastMidi)
				primary = cell;
		}
		if (!primary.active)
			continue;

		const int lower_midi = primary.midi - 12;
		if (lower_midi < min_midi || midi_pitch_class(lower_midi) != pitch_class)
			continue;

		const float primary_probe = probe_level(powers, primary.midi);
		const float lower_probe = probe_level(powers, lower_midi);
		if (primary_probe <= 1.0e-6f)
			continue;
		const bool lower_probe_supported =
			(lower_probe >= primary_probe * 0.020f && lower_probe <= primary_probe * 1.15f) ||
			(lower_midi >= 60 && lower_probe >= primary_probe * 2.0f);
		const float lower_fifth = note_grid_midi_level(grid, lower_midi + 19);
		const float lower_major_third = note_grid_midi_level(grid, lower_midi + 28);
		const bool lower_harmonic_stack_supported =
			primary.midi >= 60 && lower_midi + 28 <= kLastMidi &&
			lower_fifth >= primary.level * 0.28f &&
			lower_major_third >= primary.level * 0.12f &&
			lower_fifth + lower_major_third >= primary.level * 0.45f;
		if (!lower_probe_supported && !lower_harmonic_stack_supported)
			continue;

		bool supported_primary = false;
		for (std::size_t i = 0; i < debug_count; ++i) {
			const FullMixDebugCandidate &debug = ownership.debug_candidates[i];
			if (debug.midi != primary.midi || debug.owner != InstrumentKind::Other)
				continue;
			if (debug.ownership_confidence < 0.70f || debug.pitch_confidence < 0.45f ||
			    debug.periodicity < 0.55f)
				continue;
			supported_primary = true;
			break;
		}
		if (!supported_primary)
			continue;

		changed = promote_note_grid_primary_midi(grid, lower_midi, primary.level) || changed;
	}

	if (changed)
		write_note_grid_label(state, grid, preferred_root);
}

void prefer_measured_string_lower_other_octave_primary(NoteGrid &grid, InstrumentState &state,
						       const FullMixOwnership &ownership,
						       int min_midi, int preferred_root)
{
	min_midi = std::max(min_midi, kFirstMidi);
	bool changed = false;
	const std::size_t debug_count =
		std::min<std::size_t>(ownership.debug_candidate_count, ownership.debug_candidates.size());

	for (int pitch_class = 0; pitch_class < 12; ++pitch_class) {
		NoteCell primary = {};
		for (const auto &row : grid.rows) {
			const NoteCell &cell = row[pitch_class];
			if (cell.active) {
				primary = cell;
				break;
			}
		}
		if (!primary.active)
			continue;

		int supported_midi = -1;
		float supported_level = 0.0f;
		float supported_debug_score = 0.0f;
		for (std::size_t i = 0; i < debug_count; ++i) {
			const FullMixDebugCandidate &debug = ownership.debug_candidates[i];
			if (debug.midi < min_midi || debug.midi >= primary.midi ||
			    midi_pitch_class(debug.midi) != pitch_class)
				continue;
			if (primary.midi - debug.midi != 12)
				continue;
			if (debug.owner != InstrumentKind::Other)
				continue;
			if (debug.ownership_confidence < 0.775f || debug.ownership_confidence >= 0.80f)
				continue;
			if (debug.pitch_confidence < 0.65f || debug.periodicity < 0.70f)
				continue;

			const float visible_level = note_grid_midi_level(grid, debug.midi);
			const float raw_level = ownership_global_note_level(ownership, debug.midi);
			if (visible_level < 0.10f)
				continue;

			const float score = std::max({visible_level, raw_level, debug.ownership_confidence});
			if (supported_midi < 0 || debug.ownership_confidence > supported_debug_score ||
			    (debug.ownership_confidence == supported_debug_score && score > supported_level) ||
			    (debug.ownership_confidence == supported_debug_score && score == supported_level &&
			     debug.midi < supported_midi)) {
				supported_midi = debug.midi;
				supported_level = score;
				supported_debug_score = debug.ownership_confidence;
			}
		}
		if (supported_midi < 0)
			continue;
		changed = promote_note_grid_primary_midi(grid, supported_midi,
							 std::max(supported_level, primary.level)) ||
			  changed;
	}

	if (changed)
		write_note_grid_label(state, grid, preferred_root);
}

void prefer_probe_supported_lower_string_primary(NoteGrid &grid, InstrumentState &state,
						const FullMixOwnership &ownership,
						const std::array<float, kNoteProbeCount> &powers,
						int min_midi, int preferred_root)
{
	min_midi = std::max(min_midi, kFirstMidi);
	bool changed = false;

	for (int pitch_class = 0; pitch_class < 12; ++pitch_class) {
		NoteCell primary = {};
		for (const auto &row : grid.rows) {
			const NoteCell &cell = row[pitch_class];
			if (cell.active && cell.midi >= kFirstMidi && cell.midi <= kLastMidi) {
				primary = cell;
				break;
			}
		}
		if (!primary.active) {
			const NoteCell &cell = grid.cells[pitch_class];
			if (cell.active && cell.midi >= kFirstMidi && cell.midi <= kLastMidi)
				primary = cell;
		}
		if (!primary.active)
			continue;
		const bool fundamental_primary_supported =
			full_mix_debug_other_fundamental_primary_supported(ownership, primary.midi);

		const float primary_probe = probe_level(powers, primary.midi);
		if (primary_probe <= 1.0e-6f)
			continue;

		int supported_midi = -1;
		float supported_ratio = 0.0f;
		for (int octave_delta : {12, 24}) {
			const int lower_midi = primary.midi - octave_delta;
			if (lower_midi < min_midi || lower_midi > kLastMidi ||
			    midi_pitch_class(lower_midi) != pitch_class)
				continue;

			const float lower_probe = probe_level(powers, lower_midi);
			const float lower_ratio = lower_probe / primary_probe;
			const float lower_second_octave_ratio =
				probe_level(powers, lower_midi + 24) / primary_probe;
			const float lower_major_third_ratio =
				probe_level(powers, lower_midi + 28) / primary_probe;
			const bool low_e1_supported =
				primary.midi == 40 && lower_midi == 28 && lower_ratio >= 0.030f &&
				lower_ratio <= 0.045f && lower_second_octave_ratio >= 0.70f &&
				lower_major_third_ratio >= 0.20f;
			const bool low_g1_supported =
				primary.midi == 43 && lower_midi == 31 && lower_ratio >= 0.065f &&
				lower_ratio <= 0.090f;
			const bool direct_octave_supported =
				octave_delta == 12 && primary.midi >= 60 && lower_ratio >= 0.040f;
			const bool double_octave_supported =
				octave_delta == 24 && primary.midi >= 72 && lower_ratio >= 0.080f &&
				note_grid_midi_level(grid, primary.midi - 12) >= primary.level * 0.55f;
			if (!low_e1_supported && !low_g1_supported && !direct_octave_supported &&
			    !double_octave_supported)
				continue;
			if (fundamental_primary_supported && !low_e1_supported && !low_g1_supported)
				continue;

			if (supported_midi < 0 || lower_midi < supported_midi ||
			    (lower_midi == supported_midi && lower_ratio > supported_ratio)) {
				supported_midi = lower_midi;
				supported_ratio = lower_ratio;
			}
		}

		if (supported_midi < 0)
			continue;
		changed = promote_note_grid_primary_midi(grid, supported_midi, primary.level) || changed;
	}

	if (changed)
		write_note_grid_label(state, grid, preferred_root);
}

bool low_wind_other_alias_debug_supported(const FullMixOwnership &ownership, int lower_midi, int primary_midi)
{
	const int pitch_class = midi_pitch_class(lower_midi);
	const std::size_t debug_count =
		std::min<std::size_t>(ownership.debug_candidate_count, ownership.debug_candidates.size());
	for (std::size_t i = 0; i < debug_count; ++i) {
		const FullMixDebugCandidate &debug = ownership.debug_candidates[i];
		if (debug.midi < lower_midi + 12 || debug.midi > lower_midi + 36 ||
		    debug.midi > std::max(primary_midi, lower_midi + 24) ||
		    midi_pitch_class(debug.midi) != pitch_class)
			continue;
		if (!full_mix_display_mirror_supported(FullMixDisplayRow::Other, debug, debug.midi))
			continue;
		if (debug.owner == InstrumentKind::Keyboard && debug.keyboard_score >= 0.70f &&
		    debug.other_score < 0.35f)
			continue;
		if (debug.periodicity < 0.45f && debug.pitch_confidence < 0.12f)
			continue;
		if (debug.local_noise_level > 0.82f || debug.harmonic_fit_error > 5.8f)
			continue;
		const float other_support = std::max(debug.other_score, debug.ownership_confidence);
		const bool named_other_support =
			debug.owner == InstrumentKind::Other && other_support >= 0.58f;
		const bool ambiguous_wind_support =
			debug.owner == InstrumentKind::Ambiguous &&
			(debug.other_score >= 0.20f || debug.guitar_score >= 0.35f);
		const bool guitar_reed_support =
			debug.owner == InstrumentKind::Guitar &&
			(debug.other_score >= 0.20f || guitar_owned_reed_other_display_supported(debug));
		if (named_other_support || ambiguous_wind_support || guitar_reed_support)
			return true;
	}
	return false;
}

void prefer_probe_supported_low_wind_other_primary(NoteGrid &grid, InstrumentState &state,
						   const FullMixOwnership &ownership,
						   const std::array<float, kNoteProbeCount> &powers,
						   int min_midi, int preferred_root,
						   const NoteGrid *bass_grid = nullptr)
{
	min_midi = std::max(min_midi, kFirstMidi);
	bool changed = false;

	for (int pitch_class = 0; pitch_class < 12; ++pitch_class) {
		const NoteCell primary = note_grid_primary_cell_for_pitch_class(grid, pitch_class);
		if (!primary.active)
			continue;

		const float primary_probe = probe_level(powers, primary.midi);
		if (primary_probe <= 1.0e-6f)
			continue;

		int supported_midi = -1;
		float supported_score = 0.0f;
		for (int octave_delta : {12, 24}) {
			const int lower_midi = primary.midi - octave_delta;
			if (lower_midi < min_midi || lower_midi < 36 || lower_midi > 47 ||
			    midi_pitch_class(lower_midi) != pitch_class)
				continue;
			if (bass_grid &&
			    note_grid_midi_level(*bass_grid, lower_midi) >=
				    std::max(0.34f, primary.level * 0.30f))
				continue;

			const float lower_probe = probe_level(powers, lower_midi);
			if (lower_probe < primary_probe * 0.12f)
				continue;

			const float fifth = probe_level(powers, lower_midi + 19);
			const float second_octave = probe_level(powers, lower_midi + 24);
			const float upper_major_third = probe_level(powers, lower_midi + 28);
			const float upper_fifth = probe_level(powers, lower_midi + 31);
			const float third_octave = probe_level(powers, lower_midi + 36);
			const bool third_octave_shadow =
				third_octave >= lower_probe * 0.95f &&
				second_octave >= lower_probe * 0.32f;
			const bool dense_upper_wind_stack =
				second_octave >= lower_probe * 0.70f &&
				upper_fifth >= lower_probe * 0.70f &&
				fifth >= lower_probe * 0.32f &&
				upper_major_third <= std::max(lower_probe * 1.10f, second_octave * 0.90f);
			if (!third_octave_shadow && !dense_upper_wind_stack)
				continue;
			if (!low_wind_other_alias_debug_supported(ownership, lower_midi, primary.midi))
				continue;

			const float score =
				std::max({lower_probe, fifth * 0.72f, second_octave * 0.82f,
					  upper_fifth * 0.72f, third_octave * 0.64f});
			if (supported_midi < 0 || lower_midi < supported_midi ||
			    (lower_midi == supported_midi && score > supported_score)) {
				supported_midi = lower_midi;
				supported_score = score;
			}
		}

		if (supported_midi < 0)
			continue;
		changed = promote_note_grid_primary_midi(grid, supported_midi,
							 std::max(primary.level, supported_score)) ||
			  changed;
	}

	if (changed)
		write_note_grid_label(state, grid, preferred_root);
}

bool measured_missing_low_sax_fundamental_supported(const FullMixDebugCandidate &debug)
{
	// Five Good Sounds tenor-sax windows contain a strong, Other-owned first
	// overtone with the fundamental absent from the raw candidate list. The
	// profile has no protected-row overlap across the current real-audio suite.
	const int lower_midi = debug.midi - 12;
	return lower_midi >= 36 && lower_midi <= 47 &&
	       debug.owner == InstrumentKind::Other && debug.other_score > 0.0f &&
	       debug.other_score >= debug.guitar_score * 6.898f &&
	       debug.harmonic_ratios[3] <= 0.053f && debug.third_octave_ratio >= 0.087f;
}

void promote_measured_missing_low_sax_fundamentals(NoteGrid &grid, InstrumentState &state,
								 const FullMixOwnership &ownership, int preferred_root)
{
	bool changed = false;
	const std::size_t debug_count =
		std::min<std::size_t>(ownership.debug_candidate_count, ownership.debug_candidates.size());
	for (std::size_t i = 0; i < debug_count; ++i) {
		const FullMixDebugCandidate &debug = ownership.debug_candidates[i];
		if (!measured_missing_low_sax_fundamental_supported(debug))
			continue;
		const int lower_midi = debug.midi - 12;
		if (note_grid_midi_level(grid, lower_midi) >= 0.18f)
			continue;
		const float inferred_level = std::clamp(debug.other_score, 0.18f, 0.91f);
		write_note_grid_cell(grid, NoteCandidate{lower_midi, inferred_level}, inferred_level,
				     inferred_level);
		changed = true;
	}
	if (changed)
		write_note_grid_label(state, grid, preferred_root);
}

