		boost_drum_level(Ride, 0.34f);
	// Sparse low-RMS ride strokes retain a compact cymbal envelope despite a
	// dominant kick body; the bounded onset excludes long-decay bleed.
	const bool low_rms_embedded_ride_recovery =
		drum_detection_enabled && !one_shot_drum_source && drum_transient_ratio >= 1.75f &&
		drum_level_[Ride] <= 0.30f && ride_trigger_ratio_after_detection >= 6.0f &&
		rms >= 0.035f && rms <= 0.060f && onset >= 20.0f && onset <= 40.0f &&
		snapshot.low_energy >= 0.84f && snapshot.low_energy <= 0.88f &&
		snapshot.mid_energy >= 0.10f && snapshot.mid_energy <= 0.14f &&
		snapshot.high_energy >= 0.01f && snapshot.high_energy <= 0.03f &&
		drum_segment_bands[Ride] >= 0.95f &&
		drum_segment_bands[Ride] >= strongest_cymbal_drum * 0.42f;
	if (low_rms_embedded_ride_recovery)
		boost_drum_level(Ride, 0.34f);
	const bool compact_low_rms_ride_recovery =
		drum_detection_enabled && !one_shot_drum_source && drum_level_[Ride] <= 0.30f &&
		ride_trigger_ratio_after_detection >= 3.0f && ride_trigger_ratio_after_detection <= 4.0f &&
		drum_transient_ratio >= 2.0f && drum_transient_ratio <= 2.1f && onset >= 3.0f && onset <= 3.5f &&
		rms >= 0.035f && rms <= 0.045f && snapshot.low_energy >= 0.84f && snapshot.low_energy <= 0.86f &&
		snapshot.mid_energy >= 0.11f && snapshot.mid_energy <= 0.13f && snapshot.high_energy >= 0.02f &&
		snapshot.high_energy <= 0.04f && drum_segment_bands[Ride] >= 1.4f && drum_segment_bands[Ride] <= 1.7f &&
		drum_segment_bands[Ride] >= strongest_cymbal_drum * 0.95f;
	if (compact_low_rms_ride_recovery)
		boost_drum_level(Ride, 0.34f);
	const bool broad_low_dominant_ride_recovery =
		drum_detection_enabled && !one_shot_drum_source && drum_level_[Ride] <= 0.30f &&
		ride_trigger_ratio_after_detection >= 10.0f && ride_trigger_ratio_after_detection <= 11.0f &&
		drum_transient_ratio >= 2.0f && drum_transient_ratio <= 2.2f && onset >= 16.0f && onset <= 18.0f &&
		rms >= 0.11f && rms <= 0.12f && snapshot.low_energy >= 0.86f && snapshot.low_energy <= 0.90f &&
		snapshot.mid_energy >= 0.08f && snapshot.mid_energy <= 0.10f && snapshot.high_energy >= 0.02f &&
		snapshot.high_energy <= 0.04f && drum_segment_bands[Ride] >= 3.0f && drum_segment_bands[Ride] <= 3.2f &&
		drum_segment_bands[Ride] >= strongest_cymbal_drum * 0.95f;
	if (broad_low_dominant_ride_recovery)
		boost_drum_level(Ride, 0.34f);
	const bool mid_heavy_ride_recovery =
		drum_detection_enabled && !one_shot_drum_source && drum_level_[Ride] <= 0.30f &&
		ride_trigger_ratio_after_detection >= 8.0f && ride_trigger_ratio_after_detection <= 10.0f &&
		drum_transient_ratio >= 1.80f && drum_transient_ratio <= 1.95f && onset >= 30.0f && onset <= 35.0f &&
		rms >= 0.080f && rms <= 0.090f && snapshot.low_energy >= 0.15f && snapshot.low_energy <= 0.20f &&
		snapshot.mid_energy >= 0.55f && snapshot.mid_energy <= 0.65f && snapshot.high_energy >= 0.20f &&
		snapshot.high_energy <= 0.28f && drum_segment_bands[Ride] >= 2.1f && drum_segment_bands[Ride] <= 2.5f &&
		drum_segment_bands[Ride] >= strongest_cymbal_drum * 0.95f;
	if (mid_heavy_ride_recovery)
		boost_drum_level(Ride, 0.34f);
	const bool compact_long_onset_ride_recovery =
		drum_detection_enabled && !one_shot_drum_source && drum_level_[Ride] <= 0.30f &&
		ride_trigger_ratio_after_detection >= 4.0f && ride_trigger_ratio_after_detection <= 5.0f &&
		drum_transient_ratio >= 2.3f && drum_transient_ratio <= 2.5f && onset >= 20.0f && onset <= 23.0f &&
		rms >= 0.035f && rms <= 0.045f && snapshot.low_energy >= 0.84f && snapshot.low_energy <= 0.86f &&
		snapshot.mid_energy >= 0.11f && snapshot.mid_energy <= 0.15f && snapshot.high_energy >= 0.01f &&
		snapshot.high_energy <= 0.03f && drum_segment_bands[Ride] >= 0.55f && drum_segment_bands[Ride] <= 0.65f &&
		drum_segment_bands[Ride] >= strongest_cymbal_drum * 0.95f;
	if (compact_long_onset_ride_recovery)
		boost_drum_level(Ride, 0.34f);
	// A rare low-RMS crash onset is visibly isolated from the surrounding body
	// energy once the abrupt attack exceeds the long-onset guard.
	const float crash_trigger_ratio_after_detection =
		snapshot.drum_debug_trigger_scores[Crash] /
		(snapshot.drum_debug_trigger_thresholds[Crash] + 1.0e-6f);
	const bool long_onset_low_rms_crash_recovery =
		drum_detection_enabled && !one_shot_drum_source && drum_transient_ratio >= 1.75f &&
		drum_level_[Crash] <= 0.30f && crash_trigger_ratio_after_detection >= 1.0f &&
		onset >= 800.0f && rms <= 0.060f &&
		snapshot.low_energy >= 0.84f && snapshot.mid_energy <= 0.14f &&
		snapshot.high_energy <= 0.03f &&
		drum_segment_bands[Crash] >= 1.50f &&
		drum_segment_bands[Crash] >= strongest_cymbal_drum * 0.32f;
	if (long_onset_low_rms_crash_recovery)
		boost_drum_level(Crash, 0.34f);
	// A shorter low-RMS crash onset is still distinct from bleed when its
	// cymbal segment remains a substantial share of the local cymbal energy.
	const bool mid_onset_low_rms_crash_recovery =
		drum_detection_enabled && !one_shot_drum_source && drum_transient_ratio >= 1.50f &&
		drum_level_[Crash] <= 0.30f && crash_trigger_ratio_after_detection >= 1.0f &&
		onset >= 20.0f && onset <= 40.0f && rms >= 0.040f && rms <= 0.060f &&
		snapshot.low_energy >= 0.82f && snapshot.low_energy <= 0.86f &&
		snapshot.mid_energy >= 0.11f && snapshot.mid_energy <= 0.15f &&
		snapshot.high_energy >= 0.02f && snapshot.high_energy <= 0.04f &&
		drum_segment_bands[Crash] >= 1.0f && drum_segment_bands[Crash] <= 1.5f &&
		drum_segment_bands[Crash] >= strongest_cymbal_drum * 0.65f;
	if (mid_onset_low_rms_crash_recovery)
		boost_drum_level(Crash, 0.34f);
	// A short balanced-spectrum crash can land at threshold beneath a snare
	// without having the low-dominant shape of ordinary drum bleed.
	const bool short_balanced_crash_recovery =
		drum_detection_enabled && !one_shot_drum_source && drum_level_[Crash] <= 0.30f &&
		crash_trigger_ratio_after_detection >= 1.0f && crash_trigger_ratio_after_detection <= 1.10f &&
		drum_transient_ratio >= 1.60f && drum_transient_ratio <= 1.70f &&
		onset >= 2.5f && onset <= 3.0f && rms >= 0.065f && rms <= 0.080f &&
		snapshot.low_energy >= 0.65f && snapshot.low_energy <= 0.73f &&
		snapshot.mid_energy >= 0.22f && snapshot.mid_energy <= 0.28f &&
		snapshot.high_energy >= 0.04f && snapshot.high_energy <= 0.08f &&
		drum_segment_bands[Crash] >= 1.0f && drum_segment_bands[Crash] <= 1.2f &&
		drum_segment_bands[Crash] >= strongest_cymbal_drum * 0.70f;
	if (short_balanced_crash_recovery)
		boost_drum_level(Crash, 0.34f);
